/* DAWAH X — ahmad, অধ্যায় 54 · খণ্ড 54 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][54]=[[10601,10601,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا بِحَصَاةٍ ثُمَّ ‏ ‏نَهَى أَنْ يَبْصُقَ الرَّجُلُ بَيْنَ يَدَيْهِ وَعَنْ يَمِينِهِ وَقَالَ لِيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[10602,10602,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏اخْتِنَاثِ ‏ ‏الْأَسْقِيَةِ ‏","","",""],[10603,10603,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً ‏ ‏وَقَالَ ‏ ‏مَرَّةً يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغُسْلُ يَوْمَ الْجُمُعَةِ قَالَ هُوَ وَاجِبٌ عَلَى كُلِّ ‏ ‏مُحْتَلِمٍ ‏","","",""],[10604,10604,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْإِزَارِ ‏ ‏شَيْئًا قَالَ نَعَمْ تَعَلَّمْ سَمِعْتُهُ يَقُولُ ‏ ‏إِزْرَةُ ‏ ‏الْمُؤْمِنِ إِلَى أَنْصَافِ سَاقَيْهِ لَا ‏ ‏جُنَاحَ ‏ ‏فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ وَمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ هُوَ فِي النَّارِ يَقُولُهَا ثَلَاثَ مَرَّاتٍ ‏","","",""],[10605,10605,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي حَلْقَةٍ مِنْ حِلَقِ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءَنَا ‏ ‏أَبُو مُوسَى ‏ ‏كَأَنَّهُ مَذْعُورٌ فَقَالَ إِنَّ ‏ ‏عُمَرَ ‏ ‏أَمَرَنِي أَنْ آتِيَهُ فَأَتَيْتُهُ فَاسْتَأْذَنْتُ ثَلَاثًا فَلَمْ يُؤْذَنْ لِي فَرَجَعْتُ وَقَدْ قَالَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ فَقَالَ لَتَجِيئَنَّ ‏ ‏بِبَيِّنَةٍ ‏ ‏عَلَى الَّذِي تَقُولُ وَإِلَّا أَوْجَعْتُكَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَأَتَانَا ‏ ‏أَبُو مُوسَى ‏ ‏مَذْعُورًا ‏ ‏أَوْ قَالَ فَزِعًا ‏ ‏فَقَالَ أَسْتَشْهِدُكُمْ فَقَالَ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏لَا يَقُومُ مَعَكَ إِلَّا أَصْغَرُ الْقَوْمِ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَكُنْتُ أَصْغَرَهُمْ فَقُمْتُ مَعَهُ وَشَهِدْتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ ‏","","",""],[10606,10606,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً فَذَكَرَ فِيهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏أَوْسُقٍ ‏ ‏صَدَقَةٌ ‏","","",""],[10607,10607,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي صَعْصَعَةَ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَكَانَ فِي حُجْرَةٍ فَقَالَ لِي يَا بُنَيَّ إِذَا أَذَّنْتَ فَارْفَعْ صَوْتَكَ بِالْأَذَانِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ شَيْءٌ يَسْمَعُهُ إِلَّا شَهِدَ لَهُ جِنٌّ وَلَا إِنْسٌ وَلَا حَجَرٌ ‏ ‏و قَالَ ‏ ‏مَرَّةً يَا بُنَيَّ إِذَا كُنْتَ فِي الْبَرَارِيِّ فَارْفَعْ صَوْتَكَ بِالْأَذَانِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَا يَسْمَعُهُ جِنٌّ وَلَا إِنْسٌ وَلَا حَجَرٌ وَلَا شَيْءٌ يَسْمَعُهُ إِلَّا شَهِدَ لَهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَسُفْيَانُ ‏ ‏مُخْطِئٌ فِي اسْمِهِ وَالصَّوَابُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏","","",""],[10608,10608,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي صَعْصَعَةَ ‏ ‏شَيْخٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الرَّجُلِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا ‏ ‏شَعَفَ ‏ ‏الْجِبَالِ وَمَوَاقِعَ ‏ ‏الْقَطْرِ ‏ ‏يَفِرُّ بِدِينِهِ مِنْ الْفِتَنِ ‏","","",""],[10609,10609,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قُلْتُ ‏ ‏سُفْيَانُ ‏ ‏سَمِعَهُ قَالَ زَعَمَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةٍ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ ‏","","",""],[10610,10610,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَابْنُ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏اعْتَكَفَ ‏ ‏الْعَشْرَ الْوَسَطَ ‏ ‏وَاعْتَكَفْنَا ‏ ‏مَعَهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا كَانَ صَبِيحَةُ عِشْرِينَ مَرَّ بِنَا وَنَحْنُ نَنْقُلُ مَتَاعَنَا فَقَالَ مَنْ كَانَ ‏ ‏مُعْتَكِفًا ‏ ‏فَلْيَكُنْ فِي ‏ ‏مُعْتَكَفِهِ ‏ ‏إِنِّي رَأَيْتُ هَذِهِ اللَّيْلَةَ فَنُسِّيتُهَا وَرَأَيْتُنِي أَسْجُدُ فِي مَاءٍ وَطِينٍ وَعَرِيشُ الْمَسْجِدِ جَرِيدٌ فَهَاجَتْ السَّمَاءُ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ عَلَى أَنْفِهِ وَجَبْهَتِهِ أَثَرَ الْمَاءِ وَالطِّينِ ‏","","",""],[10611,10611,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ سَعْدِ بْنِ أَبِي سَرْحٍ ‏ ‏سَمِعَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ مَا يُخْرِجُ اللَّهُ مِنْ نَبَاتِ الْأَرْضِ وَزَهْرَةِ الدُّنْيَا فَقَالَ رَجُلٌ أَيْ رَسُولَ اللَّهِ ‏ ‏أَوَ يَأْتِي الْخَيْرُ بِالشَّرِّ فَسَكَتَ حَتَّى رَأَيْنَا أَنَّهُ يَنْزِلُ عَلَيْهِ قَالَ وَغَشِيَهُ ‏ ‏بُهْرٌ ‏ ‏وَعَرَقٌ فَقَالَ أَيْنَ السَّائِلُ فَقَالَ هَا أَنَا وَلَمْ أُرِدْ إِلَّا خَيْرًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ إِنَّ الْخَيْرَ لَا يَأْتِي إِلَّا بِالْخَيْرِ وَلَكِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَكَانَ مَا يُنْبِتُ الرَّبِيعُ يَقْتُلُ ‏ ‏حَبَطًا ‏ ‏أَوْ ‏ ‏يُلِمُّ ‏ ‏إِلَّا آكِلَةُ الْخَضِرِ فَإِنَّهَا أَكَلَتْ حَتَّى ‏ ‏امْتَدَّتْ خَاصِرَتَاهَا ‏ ‏وَاسْتَقْبَلَتْ الشَّمْسَ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ عَادَتْ فَأَكَلَتْ فَمَنْ أَخَذَهَا بِحَقِّهَا بُورِكَ لَهُ فِيهِ وَمَنْ أَخَذَهَا بِغَيْرِ حَقِّهَا لَمْ يُبَارَكْ لَهُ وَكَانَ كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَكَانَ ‏ ‏الْأَعْمَشُ ‏ ‏يَسْأَلُنِي عَنْ هَذَا الْحَدِيثِ ‏","","",""],[10612,10612,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَتَوَضَّأُ إِذَا جَامَعَ وَإِذَا أَرَادَ أَنْ يَرْجِعَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَدْرَكَ ‏ ‏الْحَرَّةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏يَقْتُلُ ‏ ‏حَبَطًا ‏ ‏أَوْ ‏ ‏خَبْطًا ‏ ‏وَإِنَّمَا هُوَ ‏ ‏حَبَطًا ‏","","",""],[10613,10613,"","","‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ مُسْتَخْلِفُكُمْ فِيهَا فَيَنْظُرُ كَيْفَ تَعْمَلُونَ أَلَا وَإِنَّ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ عِنْدَ اسْتِهِ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10614,10614,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَيْفَ أَنْعَمُ وَقَدْ الْتَقَمَ صَاحِبُ الْقَرْنِ الْقَرْنَ ‏ ‏وَحَنَى ‏ ‏جَبْهَتَهُ وَأَصْغَى سَمْعَهُ يَنْظُرُ مَتَى يُؤْمَرُ قَالَ الْمُسْلِمُونَ يَا رَسُولَ اللَّهِ فَمَا نَقُولُ قَالَ قُولُوا ‏ ‏حَسْبُنَا ‏ ‏اللَّهُ وَنِعْمَ الْوَكِيلُ عَلَى اللَّهِ تَوَكَّلْنَا ‏","","",""],[10615,10615,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏رِوَايَةً يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرُ الْمَرْأَةُ ثَلَاثَةَ أَيَّامٍ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ ‏","","",""],[10616,10616,"","","‏ ‏وَنَهَى عَنْ صِيَامِ الْفِطْرِ وَيَوْمِ النَّحْرِ ‏","","",""],[10617,10617,"","","‏ ‏وَنَهَى عَنْ صَلَاتَيْنِ صَلَاةٍ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[10618,10618,"","","‏ ‏وَلَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَسْجِدِ الْأَقْصَى ‏","","",""],[10619,10619,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي عَلَى النَّاسِ زَمَانٌ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيُقَالُ هَلْ فِيكُمْ مَنْ صَاحَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ثُمَّ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيُقَالُ هَلْ فِيكُمْ مَنْ صَاحَبَ مَنْ صَاحَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ثُمَّ يَغْزُو ‏ ‏فِئَامٌ ‏ ‏مِنْ النَّاسِ فَيَقُولُونَ هَلْ فِيكُمْ مَنْ صَاحَبَ مَنْ صَاحَبَ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ نَعَمْ فَيُفْتَحُ لَهُمْ ‏","","",""],[10620,10620,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعَ ‏ ‏عَمْرًا ‏ ‏عَنْ ‏ ‏عَتَّابِ بْنِ حُنَيْنٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏لَا أَدْرِي مَنْ ‏ ‏عَتَّابٌ ‏ ‏لَوْ أَمْسَكَ اللَّهُ ‏ ‏الْقَطْرَ ‏ ‏عَنْ النَّاسِ سَبْعَ سِنِينَ ثُمَّ أَرْسَلَهُ لَأَصْبَحَتْ طَائِفَةٌ بِهِ كَافِرِينَ يَقُولُونَ مُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏الْمِجْدَحِ ‏","","",""],[10621,10621,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكُ بْنُ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ إِلَى ‏ ‏قُبَاءَ ‏","","",""],[10622,10622,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ قِيمَةُ ‏ ‏أُوقِيَّةٍ ‏ ‏فَقَدْ ‏ ‏أَلْحَفَ ‏","","",""],[10623,10623,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ ‏ ‏حَائِطًا ‏ ‏فَأَرَادَ أَنْ يَأْكُلَ فَلْيُنَادِ يَا صَاحِبَ ‏ ‏الْحَائِطِ ‏ ‏ثَلَاثًا فَإِنْ أَجَابَهُ وَإِلَّا فَلْيَأْكُلْ وَإِذَا مَرَّ أَحَدُكُمْ بِإِبِلٍ فَأَرَادَ أَنْ يَشْرَبَ مِنْ أَلْبَانِهَا فَلْيُنَادِ يَا صَاحِبَ الْإِبِلِ ‏ ‏أَوْ يَا رَاعِيَ الْإِبِلِ ‏ ‏فَإِنْ أَجَابَهُ وَإِلَّا فَلْيَشْرَبْ وَالضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا زَادَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[10624,10624,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَمَارَى ‏ ‏رَجُلَانِ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ فَقَالَ رَجُلٌ هُوَ ‏ ‏مَسْجِدُ قُبَاءَ ‏ ‏وَقَالَ رَجُلٌ هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ ‏ ‏مَسْجِدِي ‏","","",""],[10625,10625,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏حَدَّثَ أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نُهُوا عَنْ ‏ ‏الصَّرْفِ ‏ ‏وَرَفَعَهُ رَجُلَانِ مِنْهُمْ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10626,10626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏قَالَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏حَدَّثَ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نُهُوا عَنْ ‏ ‏الصَّرْفِ ‏ ‏رَفَعَهُ رَجُلَانِ مِنْهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10627,10627,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَجَابِرٍ ‏ ‏اثْنَيْنِ مِنْ هَؤُلَاءِ الثَّلَاثَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الصَّرْفِ ‏","","",""],[10628,10628,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُونَ فِي الدُّنْيَا عَلَى ثَلَاثَةِ أَجْزَاءٍ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِي يَأْمَنُهُ النَّاسُ عَلَى أَمْوَالِهِمْ وَأَنْفُسِهِمْ ثُمَّ الَّذِي إِذَا أَشْرَفَ عَلَى طَمَعٍ تَرَكَهُ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[10629,10629,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رُبَيْحُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشٍ أَقْرَنَ وَقَالَ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[10630,10630,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعَيَّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْمُزَابَنَةِ وَالْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةُ اشْتِرَاءُ التَّمْرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ وَالْمُحَاقَلَةُ ‏ ‏اسْتِكْرَاءُ ‏ ‏الْأَرْضِ ‏ ‏بِالْحِنْطَةِ ‏","","",""],[10631,10631,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ الْمَشْرِقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ قَالَ فَشَقَّ ذَلِكَ عَلَى أَصْحَابِهِ فَقَالُوا مَنْ يُطِيقُ ذَلِكَ قَالَ ‏ ‏يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَهِيَ ثُلُثُ الْقُرْآنِ ‏","","",""],[10632,10632,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا رَأَى أَحَدُكُمْ الرُّؤْيَا يُحِبُّهَا فَإِنَّمَا هِيَ مِنْ اللَّهِ فَلْيَحْمَدْ اللَّهَ عَلَيْهَا وَلْيُحَدِّثْ بِهَا فَإِذَا رَأَى غَيْرَ ذَلِكَ مِمَّا يَكْرَهُ فَإِنَّمَا هِيَ مِنْ الشَّيْطَانِ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ شَرِّهَا وَلَا يَذْكُرُهَا لِأَحَدٍ فَإِنَّهَا لَا تَضُرُّهُ ‏","","",""],[10633,10633,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏فَأَيُّكُمْ أَرَادَ أَنْ ‏ ‏يُوَاصِلَ ‏ ‏فَلْيُوَاصِلْ ‏ ‏حَتَّى ‏ ‏السَّحَرِ ‏ ‏فَقَالُوا إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ كَهَيْئَتِكُمْ إِنِّي أَبِيتُ لِي مُطْعِمٌ يُطْعِمُنِي وَسَاقٍ ‏ ‏يَسْقِينِي ‏","","",""],[10634,10634,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حَلِيمَ ‏ ‏إِلَّا ذُو عِزَّةٍ وَلَا حَكِيمَ إِلَّا ذُو تَجْرِبَةٍ ‏","","",""],[10635,10635,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏يُحَنَّسَ ‏ ‏مَوْلَى ‏ ‏مُصْعَبِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نَسِيرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَرْجِ ‏ ‏إِذْ عَرَضَ شَاعِرٌ يُنْشِدُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا الشَّيْطَانَ ‏ ‏أَوْ أَمْسِكُوا الشَّيْطَانَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ رَجُلٍ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[10636,10636,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْخَبَّابِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُكِرَ عِنْدَهُ عَمُّهُ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَقَالَ ‏ ‏لَعَلَّهُ تَنْفَعُهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ فَيُجْعَلَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ نَارٍ يَبْلُغُ كَعْبَهُ يَغْلِي مِنْهُ دِمَاغُهُ ‏","","",""],[10637,10637,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي يَعْقُوبَ الْخَيَّاطِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ ‏ ‏مُصْعَبِ بْنِ الزُّبَيْرِ ‏ ‏الْفِطْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَسَأَلَهُ كَيْفَ كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي قَبْلَ أَنْ يَخْطُبَ فَصَلَّى يَوْمَئِذٍ قَبْلَ الْخُطْبَةِ ‏","","",""],[10638,10638,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَرَّحَتْنِي أُمِّي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ فَأَتَيْتُهُ فَقَعَدْتُ قَالَ فَاسْتَقْبَلَنِي فَقَالَ ‏ ‏مَنْ اسْتَغْنَى أَغْنَاهُ اللَّهُ وَمَنْ ‏ ‏اسْتَعَفَّ ‏ ‏أَعَفَّهُ ‏ ‏اللَّهُ وَمَنْ اسْتَكْفَى كَفَاهُ اللَّهُ وَمَنْ سَأَلَ وَلَهُ قِيمَةُ ‏ ‏أُوقِيَّةٍ ‏ ‏فَقَدْ ‏ ‏أَلْحَفَ ‏ ‏قَالَ فَقُلْتُ نَاقَتِي الْيَاقُوتَةُ هِيَ خَيْرٌ مِنْ ‏ ‏أُوقِيَّةٍ ‏ ‏فَرَجَعْتُ وَلَمْ أَسْأَلْهُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الرِّجَالِ ‏ ‏نَحْوَهُ ‏","","",""],[10639,10639,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ يَعْنِي الْقَارِئَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ وَلَا ‏ ‏الْوَرِقَ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا وَزْنًا بِوَزْنٍ مِثْلًا بِمِثْلٍ سَوَاءً بِسَوَاءٍ ‏","","",""],[10640,10640,"","","‏ ‏و قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[10641,10641,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَهَى الْمُؤْمِنُ الْوَلَدَ فِي الْجَنَّةِ كَانَ حَمْلُهُ وَوَضْعُهُ وَسِنُّهُ فِي سَاعَةٍ وَاحِدَةٍ كَمَا ‏ ‏يَشْتَهِي ‏","","",""],[10642,10642,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ ‏ ‏الْعَرَاجِينَ ‏ ‏يُمْسِكُهَا فِي يَدِهِ ‏ ‏فَدَخَلَ الْمَسْجِدَ فَرَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهَا ‏ ‏بِهِ حَتَّى أَنْقَاهَا ‏","","",""],[10643,10643,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِيهِ وَعَنْ التَّمْرِ وَالزَّبِيبِ أَنْ يُخْلَطَ بَيْنَهُمَا وَعَنْ ‏ ‏الْبُسْرِ ‏ ‏وَالتَّمْرِ أَنْ يُخْلَطَ بَيْنَهُمَا ‏","","",""],[10644,10644,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ يُجَاءُ بِالْمَوْتِ كَأَنَّهُ كَبْشٌ ‏ ‏أَمْلَحُ ‏ ‏فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ هَلْ تَعْرِفُونَ هَذَا قَالَ ‏ ‏فَيَشْرَئِبُّونَ ‏ ‏فَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ قَالَ فَيُقَالُ يَا أَهْلَ النَّارِ هَلْ تَعْرِفُونَ هَذَا قَالَ ‏ ‏فَيَشْرَئِبُّونَ ‏ ‏فَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ قَالَ فَيُؤْمَرُ بِهِ فَيُذْبَحُ قَالَ وَيُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ قَالَ ثُمَّ قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الْأَمْرُ وَهُمْ فِي غَفْلَةٍ ‏} ‏قَالَ وَأَشَارَ بِيَدِهِ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏فِي حَدِيثِهِ إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ يُجَاءُ بِالْمَوْتِ كَأَنَّهُ كَبْشٌ ‏ ‏أَمْلَحُ ‏","","",""],[10645,10645,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلِي وَمَثَلُ النَّبِيِّينَ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى دَارًا فَأَتَمَّهَا إِلَّا ‏ ‏لَبِنَةً ‏ ‏وَاحِدَةً فَجِئْتُ أَنَا فَأَتْمَمْتُ تِلْكَ ‏ ‏اللَّبِنَةَ ‏","","",""],[10646,10646,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا ‏} ‏قَالَ عَدْلًا ‏","","",""],[10647,10647,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاحِبَ الصُّورِ فَقَالَ ‏ ‏عَنْ يَمِينِهِ ‏ ‏جِبْرِيلُ ‏ ‏وَعَنْ يَسَارِهِ ‏ ‏مِيكَائِيلُ ‏ ‏عَلَيْهِمْ السَّلَام ‏","","",""],[10648,10648,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏ثَلَاثِينَ رَاكِبًا قَالَ فَنَزَلْنَا بِقَوْمٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏قَالَ فَسَأَلْنَاهُمْ أَنْ يُضَيِّفُونَا فَأَبَوْا قَالَ فَلُدِغَ سَيِّدُهُمْ قَالَ فَأَتَوْنَا فَقَالُوا فِيكُمْ أَحَدٌ ‏ ‏يَرْقِي ‏ ‏مِنْ الْعَقْرَبِ قَالَ فَقُلْتُ نَعَمْ أَنَا وَلَكِنْ لَا أَفْعَلُ حَتَّى تُعْطُونَا شَيْئًا قَالُوا فَإِنَّا ‏ ‏نُعْطِيكُمْ ثَلَاثِينَ شَاةً قَالَ فَقَرَأْتُ عَلَيْهَا ‏ ‏الْحَمْدُ لِلَّهِ ‏ ‏سَبْعَ مَرَّاتٍ قَالَ ‏ ‏فَبَرَأَ ‏ ‏قَالَ فَلَمَّا قَبَضْنَا الْغَنَمَ قَالَ ‏ ‏عَرَضَ ‏ ‏فِي أَنْفُسِنَا مِنْهَا قَالَ فَكَفَفْنَا حَتَّى أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَذَكَرْنَا ذَلِكَ لَهُ قَالَ فَقَالَ ‏ ‏أَمَا عَلِمْتَ أَنَّهَا ‏ ‏رُقْيَةٌ ‏ ‏اقْسِمُوهَا وَاضْرِبُوا لِي مَعَكُمْ ‏ ‏بِسَهْمٍ ‏","","",""],[10649,10649,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَصِيرٍ ‏","","",""],[10650,10650,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَاضِعًا طَرَفَيْهِ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[10651,10651,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَخْرَجَ ‏ ‏مَرْوَانُ ‏ ‏الْمِنْبَرَ فِي يَوْمِ عِيدٍ وَلَمْ يَكُنْ يُخْرَجُ بِهِ وَبَدَأَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ وَلَمْ يَكُنْ يُبْدَأُ بِهَا قَالَ فَقَامَ رَجُلٍ فَقَالَ يَا ‏ ‏مَرْوَانُ ‏ ‏خَالَفْتَ السُّنَّةَ أَخْرَجْتَ الْمِنْبَرَ يَوْمَ عِيدٍ وَلَمْ يَكُنْ يُخْرَجُ بِهِ فِي يَوْمِ عِيدٍ وَبَدَأْتَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ وَلَمْ يَكُنْ يُبْدَأُ بِهَا قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏مَنْ هَذَا قَالُوا فُلَانُ بْنُ فُلَانٍ قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَإِنْ اسْتَطَاعَ أَنْ يُغَيِّرَهُ بِيَدِهِ فَلْيَفْعَلْ ‏ ‏وَقَالَ مَرَّةً فَلْيُغَيِّرْهُ بِيَدِهِ ‏ ‏فَإِنْ لَمْ يَسْتَطِعْ بِيَدِهِ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ بِلِسَانِهِ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[10652,10652,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْوَلِيدِ الْوَصَّافِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يَأْوِي إِلَى فِرَاشِهِ ‏ ‏أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ ثَلَاثَ مَرَّاتٍ غَفَرَ اللَّهُ لَهُ ذُنُوبَهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ وَإِنْ كَانَتْ مِثْلَ رَمْلٍ عَالِجٍ وَإِنْ كَانَتْ مِثْلَ عَدَدِ وَرَقِ الشَّجَرِ ‏","","",""],[10653,10653,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ ‏ ‏أَسَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الذَّهَبِ بِالذَّهَبِ وَالْفِضَّةِ بِالْفِضَّةِ قَالَ سَأُخْبِرُكُمْ مَا سَمِعْتُ مِنْهُ جَاءَهُ ‏ ‏صَاحِبُ تَمْرِهِ ‏ ‏بِتَمْرٍ طَيِّبٍ وَكَانَ تَمْرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَالُ لَهُ اللَّوْنُ قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ لَكَ هَذَا التَّمْرُ الطَّيِّبُ قَالَ ‏ ‏ذَهَبْتُ ‏ ‏بِصَاعَيْنِ ‏ ‏مِنْ تَمْرِنَا وَاشْتَرَيْتُ بِهِ ‏ ‏صَاعًا ‏ ‏مِنْ هَذَا قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَيْتَ ‏ ‏قَالَ ‏ ‏ثُمَّ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَالتَّمْرُ بِالتَّمْرِ ‏ ‏أَرْبَى ‏ ‏أَمْ الْفِضَّةُ بِالْفِضَّةِ وَالذَّهَبُ بِالذَّهَبِ ‏","","",""],[10654,10654,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏اعْتَكَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشْرَ الْأَوْسَطَ مِنْ رَمَضَانَ وَهُوَ يَلْتَمِسُ لَيْلَةَ الْقَدْرِ قَبْلَ أَنْ تُبَانَ لَهُ فَلَمَّا تَقَضَّيْنَ أَمَرَ بِبُنْيَانِهِ فَنُقِضَ ثُمَّ أُبِينَتْ لَهُ أَنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ فَأَمَرَ بِالْبِنَاءِ فَأُعِيدَ ثُمَّ اعْتَكَفَ الْعَشْرَ الْأَوَاخِرَ ثُمَّ خَرَجَ عَلَى النَّاسِ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّهَا أُبِينَتْ لِي لَيْلَةُ الْقَدْرِ فَخَرَجْتُ لِأُخْبِرَكُمْ بِهَا فَجَاءَ رَجُلَانِ يَحِيفَانِ مَعَهُمَا الشَّيْطَانُ فَنُسِّيتُهَا فَالْتَمِسُوهَا فِي التَّاسِعَةِ وَالسَّابِعَةِ وَالْخَامِسَةِ ‏ ‏فَقُلْتُ ‏ ‏يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏إِنَّكُمْ أَعْلَمُ بِالْعَدَدِ مِنَّا قَالَ ‏ ‏أَنَا أَحَقُّ بِذَاكَ مِنْكُمْ فَمَا التَّاسِعَةُ وَالسَّابِعَةُ وَالْخَامِسَةُ قَالَ تَدَعُ الَّتِي تَدْعُونَ إِحْدَى وَعِشْرِينَ وَالَّتِي تَلِيهَا التَّاسِعَةُ وَتَدَعُ الَّتِي ‏ ‏تَدْعُونَ ثَلَاثَةً وَعِشْرِينَ وَالَّتِي تَلِيهَا السَّابِعَةُ وَتَدَعُ الَّتِي تَدْعُونَ خَمْسَةً وَعِشْرِينَ وَالَّتِي تَلِيهَا الْخَامِسَةُ ‏","","",""],[10655,10655,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ وَلَكِنْ نَاسٌ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏تُصِيبُهُمْ النَّارُ بِذُنُوبِهِمْ ‏ ‏أَوْ قَالَ بِخَطَايَاهُمْ ‏ ‏فَيُمِيتُهُمْ إِمَاتَةً حَتَّى إِذَا صَارُوا فَحْمًا ‏ ‏أَذِنَ ‏ ‏فِي ‏ ‏الشَّفَاعَةِ ‏ ‏فَجِيءَ بِهِمْ ‏ ‏ضَبَائِرَ ‏ ‏ضَبَائِرَ ‏ ‏ضَبَائِرَ ‏ ‏فَنَبَتُوا عَلَى أَنْهَارِ الْجَنَّةِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ ‏ ‏أَفِيضُوا ‏ ‏عَلَيْهِمْ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ قَالَ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ حِينَئِذٍ كَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ بِالْبَادِيَةِ ‏","","",""],[10656,10656,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ بِشْرِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏فَرَدَّ الْحَدِيثَ حَتَّى رَدَّهُ إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ ذَلِكَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَمَا ‏ ‏ذَاكُمْ قَالُوا الرَّجُلُ تَكُونُ لَهُ الْمَرْأَةُ تُرْضِعُ فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ وَالرَّجُلُ تَكُونُ لَهُ ‏ ‏الْجَارِيَةُ ‏ ‏فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ فَقَالَ ‏ ‏فَلَا عَلَيْكُمْ أَنْ تَفْعَلُوا ‏ ‏ذَاكُمْ فَإِنَّمَا هُوَ الْقَدَرُ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏الْحَسَنَ ‏ ‏فَقَالَ ‏ ‏فَلَا عَلَيْكُمْ لَكَأَنَّ هَذَا ‏ ‏زَجْرٌ ‏","","",""],[10657,10657,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا أَصْحَابِي فَإِنَّ أَحَدَكُمْ لَوْ أَنْفَقَ مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا مَا بَلَغَ ‏ ‏مُدَّ ‏ ‏أَحَدِهِمْ وَلَا نَصِيفَهُ ‏","","",""],[10658,10658,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَوْ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏شَكَّ ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ غَزْوَةُ ‏ ‏تَبُوكَ ‏ ‏أَصَابَ النَّاسَ مَجَاعَةٌ فَقَالُوا يَا رَسُولَ اللَّهِ لَوْ أَذِنْتَ لَنَا ‏ ‏فَنَحَرْنَا ‏ ‏نَوَاضِحَنَا ‏ ‏فَأَكَلْنَا وَادَّهَنَّا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْعَلُوا فَجَاءَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُمْ إِنْ فَعَلُوا قَلَّ الظَّهْرُ وَلَكِنْ ادْعُهُمْ بِفَضْلِ ‏ ‏أَزْوَادِهِمْ ‏ ‏ثُمَّ ادْعُ لَهُمْ عَلَيْهِ بِالْبَرَكَةِ لَعَلَّ اللَّهَ أَنْ يَجْعَلَ فِي ذَلِكَ فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنِطَعٍ ‏ ‏فَبَسَطَهُ ثُمَّ دَعَاهُمْ بِفَضْلِ ‏ ‏أَزْوَادِهِمْ ‏ ‏فَجَعَلَ الرَّجُلُ يَجِيءُ بِكَفِّ الذُّرَةِ وَالْآخَرُ بِكَفِّ التَّمْرِ وَالْآخَرُ بِالْكِسْرَةِ حَتَّى اجْتَمَعَ عَلَى ‏ ‏النِّطْعِ ‏ ‏مِنْ ذَلِكَ شَيْءٌ يَسِيرٌ ثُمَّ دَعَا عَلَيْهِ بِالْبَرَكَةِ ثُمَّ قَالَ لَهُمْ خُذُوا فِي أَوْعِيَتِكُمْ قَالَ فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا مِنْ الْعَسْكَرِ وِعَاءً إِلَّا مَلَئُوهُ وَأَكَلُوا حَتَّى شَبِعُوا وَفَضَلَتْ مِنْهُ فَضْلَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ لَا يَلْقَى اللَّهَ بِهَا عَبْدٌ غَيْرُ شَاكٍّ فَتُحْجَبَ عَنْهُ الْجَنَّةُ ‏","","",""],[10659,10659,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْمُغِيرَةِ بْنِ مُعَيْقِيبٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ عَبْدٍ الْعُتْوَارِيِّ ‏ ‏أَحَدُ ‏ ‏بَنِي لَيْثٍ ‏ ‏وَكَانَ يَتِيمًا فِي حِجْرِ ‏ ‏أَبِي سَعِيدٍ ‏ ‏سُلَيْمَانَ بْنِ عُمَرَ وَهُوَ أَبُو الْهَيْثَمِ ‏ ‏الَّذِي يَرْوِي عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يُوضَعُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ عَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏كَحَسَكِ ‏ ‏السَّعْدَانِ ‏ ‏ثُمَّ ‏ ‏يَسْتَجِيزُ ‏ ‏النَّاسُ فَنَاجٍ مُسَلَّمٌ ‏ ‏وَمَجْدُوحٌ ‏ ‏بِهِ ثُمَّ نَاجٍ وَمُحْتَبِسٌ بِهِ مَنْكُوسٌ فِيهَا فَإِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ يَفْقِدُ الْمُؤْمِنُونَ رِجَالًا كَانُوا مَعَهُمْ فِي الدُّنْيَا يُصَلُّونَ بِصَلَاتِهِمْ وَيُزَكُّونَ بِزَكَاتِهِمْ وَيَصُومُونَ صِيَامَهُمْ وَيَحُجُّونَ حَجَّهُمْ وَيَغْزُونَ غَزْوَهُمْ فَيَقُولُونَ أَيْ رَبَّنَا عِبَادٌ مِنْ عِبَادِكَ كَانُوا مَعَنَا فِي الدُّنْيَا يُصَلُّونَ صَلَاتَنَا وَيُزَكُّونَ زَكَاتَنَا وَيَصُومُونَ صِيَامَنَا وَيَحُجُّونَ حَجَّنَا وَيَغْزُونَ غَزْوَنَا لَا ‏ ‏نَرَاهُمْ فَيَقُولُ ‏ ‏اذْهَبُوا إِلَى النَّارِ فَمَنْ وَجَدْتُمْ فِيهَا مِنْهُمْ فَأَخْرِجُوهُ قَالَ فَيَجِدُونَهُمْ قَدْ أَخَذَتْهُمْ النَّارُ عَلَى قَدْرِ أَعْمَالِهِمْ فَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى قَدَمَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى نِصْفِ سَاقَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ ‏ ‏أَزِرَتْهُ ‏ ‏وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى ثَدْيَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى عُنُقِهِ وَلَمْ تَغْشَ الْوُجُوهَ فَيَسْتَخْرِجُونَهُمْ مِنْهَا فَيُطْرَحُونَ فِي مَاءِ الْحَيَاةِ قِيلَ يَا رَسُولَ اللَّهِ وَمَا مَاءُ الْحَيَاةِ قَالَ غُسْلُ أَهْلِ الْجَنَّةِ فَيَنْبُتُونَ نَبَاتَ ‏ ‏الزَّرْعَةِ ‏ ‏وَقَالَ مَرَّةً فِيهِ كَمَا تَنْبُتُ الزَّرْعَةُ فِي ‏ ‏غُثَاءِ ‏ ‏السَّيْلِ ‏ ‏ثُمَّ يَشْفَعُ الْأَنْبِيَاءُ فِي كُلِّ مَنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصًا فَيُخْرِجُونَهُمْ مِنْهَا قَالَ ثُمَّ يَتَحَنَّنُ اللَّهُ بِرَحْمَتِهِ عَلَى مَنْ فِيهَا فَمَا يَتْرُكُ فِيهَا عَبْدًا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ إِلَّا أَخْرَجَهُ مِنْهَا ‏","","",""],[10660,10660,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيَاضٌ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَحَدُنَا ‏ ‏يُصَلِّي ‏ ‏فَلَا يَدْرِي ‏ ‏كَمْ صَلَّى فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ كَمْ صَلَّى فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ وَإِذَا جَاءَ أَحَدَكُمْ الشَّيْطَانُ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فَلْيَقُلْ كَذَبْتَ إِلَّا مَا وَجَدَ رِيحَهُ بِأَنْفِهِ أَوْ سَمِعَ صَوْتَهُ بِأُذُنِهِ ‏","","",""],[10661,10661,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ فَلَا ‏ ‏يَجِدُ ‏ ‏الصَّائِمُ عَلَى الْمُفْطِرِ وَلَا الْمُفْطِرُ عَلَى الصَّائِمِ ‏ ‏يَرَوْنَ أَنَّهُ ‏ ‏يَعْنِي مَنْ وَجَدَ قُوَّةً فَصَامَ فَإِنَّ ذَلِكَ حَسَنٌ وَيَرَوْنَ أَنَّهُ مَنْ وَجَدَ ضَعْفًا فَأَفْطَرَ فَإِنَّ ذَلِكَ حَسَنٌ ‏","","",""],[10662,10662,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏لَمْ نَعُدْ أَنْ فُتِحَتْ ‏ ‏خَيْبَرُ ‏ ‏وَقَعْنَا فِي تِلْكَ ‏ ‏الْبَقْلَةِ ‏ ‏فَأَكَلْنَا مِنْهَا أَكْلًا شَدِيدًا وَنَاسٌ جِيَاعٌ ثُمَّ رَحَلْنَا إِلَى الْمَسْجِدِ فَوَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرِّيحَ فَقَالَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْخَبِيثَةِ شَيْئًا فَلَا يَقْرَبْنَا فِي الْمَسْجِدِ فَقَالَ النَّاسُ حُرِّمَتْ حُرِّمَتْ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّهُ لَيْسَ لِي تَحْرِيمُ مَا أَحَلَّ اللَّهُ وَلَكِنَّهَا شَجَرَةٌ أَكْرَهُ رِيحَهَا ‏","","",""],[10663,10663,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا سِوَى الْقُرْآنِ وَمَنْ كَتَبَ شَيْئًا سِوَى الْقُرْآنِ فَلْيَمْحُهُ ‏","","",""],[10664,10664,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّحُورُ أَكْلُهُ بَرَكَةٌ فَلَا تَدَعُوهُ وَلَوْ أَنْ يَجْرَعَ أَحَدُكُمْ جُرْعَةً مِنْ مَاءٍ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الْمُتَسَحِّرِينَ ‏","","",""],[10665,10665,"","","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا فَمَنْ كَتَبَ عَنِّي شَيْئًا فَلْيَمْحُهُ ‏","","",""],[10666,10666,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يَشْرَبُ وَهُوَ قَائِمٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏كُنَّا نَكْرَهُ ذَلِكَ ‏","","",""],[10667,10667,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَشْهَدُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ ‏ ‏عَنْ ذَاكَ ‏ ‏وَزَجَرَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَةَ لِبَوْلٍ ‏","","",""],[10668,10668,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَتَحَ ‏ ‏خَوْخَةً ‏ ‏لَهُ وَعِنْدَهُ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَخَرَجَتْ عَلَيْهِمْ حَيَّةٌ فَأَمَرَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏بِقَتْلِهَا فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ يُؤْذِنَهُنَّ قَبْلَ أَنْ يَقْتُلَهُنَّ ‏","","",""],[10669,10669,"","","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ وَمَا أَجِدُ لَكُمْ رِزْقًا أَوْسَعَ مِنْ الصَّبْرِ ‏","","",""],[10670,10670,"","","‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا قُعُودًا نَكْتُبُ مَا نَسْمَعُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ عَلَيْنَا فَقَالَ مَا هَذَا تَكْتُبُونَ فَقُلْنَا مَا نَسْمَعُ مِنْكَ فَقَالَ أَكِتَابٌ مَعَ كِتَابِ اللَّهِ فَقُلْنَا مَا نَسْمَعُ فَقَالَ اكْتُبُوا كِتَابَ اللَّهِ ‏ ‏أَمْحِضُوا ‏ ‏كِتَابَ اللَّهِ أَكِتَابٌ غَيْرُ كِتَابِ اللَّهِ ‏ ‏أَمْحِضُوا ‏ ‏كِتَابَ اللَّهِ ‏ ‏أَوْ خَلِّصُوهُ ‏ ‏قَالَ فَجَمَعْنَا مَا كَتَبْنَا فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ ثُمَّ أَحْرَقْنَاهُ بِالنَّارِ قُلْنَا أَيْ رَسُولَ اللَّهِ أَنَتَحَدَّثُ عَنْكَ قَالَ نَعَمْ ‏ ‏تَحَدَّثُوا عَنِّي وَلَا حَرَجَ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ أَنَتَحَدَّثُ عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالَ نَعَمْ تَحَدَّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ فَإِنَّكُمْ لَا تَحَدَّثُوا عَنْهُمْ بِشَيْءٍ إِلَّا وَقَدْ كَانَ فِيهِمْ أَعْجَبَ مِنْهُ ‏","","",""],[10671,10671,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفًا ‏ ‏بِعَرَفَةَ ‏ ‏يَدْعُو هَكَذَا وَرَفَعَ يَدَيْهِ حِيَالَ ‏ ‏ثَنْدُوَتَيْهِ ‏ ‏وَجَعَلَ بُطُونَ كَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[10672,10672,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ ‏","","",""],[10673,10673,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ مِنْ النَّارِ فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ ‏ ‏فَيُقْتَصُّ ‏ ‏لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ فَوَالَّذِي نَفْسِي بِيَدِهِ لَأَحَدُهُمْ ‏ ‏أَهْدَى ‏ ‏لِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا ‏","","",""],[10674,10674,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏فِرَاسُ بْنُ يَحْيَى الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَقَدْ دَخَلَ رَجُلٌ الْجَنَّةَ مَا عَمِلَ خَيْرًا قَطُّ قَالَ لِأَهْلِهِ حِينَ حَضَرَهُ الْمَوْتُ إِذَا أَنَا مِتُّ فَأَحْرِقُونِي ثُمَّ اسْحَقُونِي ثُمَّ ‏ ‏اذْرُوا ‏ ‏نِصْفِي فِي الْبَحْرِ وَنِصْفِي فِي الْبَرِّ فَأَمَرَ اللَّهُ الْبَرَّ وَالْبَحْرَ فَجَمَعَاهُ ثُمَّ قَالَ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ مَخَافَتُكَ قَالَ فَغَفَرَ لَهُ بِذَلِكَ ‏","","",""],[10675,10675,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ الْعَوْفِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوَتْرِ ‏ ‏فَقَالَ ‏ ‏أَوْتِرُوا ‏ ‏قَبْلَ الصُّبْحِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ مِنْ النَّارِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[10676,10676,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ افْتَخَرَتْ الْجَنَّةُ وَالنَّارُ فَقَالَتْ النَّارُ يَا رَبِّ يَدْخُلُنِي الْجَبَابِرَةُ وَالْمُتَكَبِّرُونَ وَالْمُلُوكُ وَالْأَشْرَافُ وَقَالَتْ الْجَنَّةُ أَيْ رَبِّ يَدْخُلُنِي الضُّعَفَاءُ وَالْفُقَرَاءُ وَالْمَسَاكِينُ فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لِلنَّارِ ‏ ‏أَنْتِ عَذَابِي أُصِيبُ بِكِ مَنْ أَشَاءُ وَقَالَ لِلْجَنَّةِ أَنْتِ رَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا ‏ ‏فَيُلْقَى فِي النَّارِ أَهْلُهَا فَتَقُولُ هَلْ مِنْ مَزِيدٍ قَالَ وَيُلْقَى فِيهَا وَتَقُولُ هَلْ مِنْ مَزِيدٍ وَيُلْقَى فِيهَا وَتَقُولُ هَلْ مِنْ مَزِيدٍ حَتَّى يَأْتِيَهَا تَبَارَكَ وَتَعَالَى فَيَضَعَ قَدَمَهُ عَلَيْهَا ‏ ‏فَتُزْوَى ‏ ‏فَتَقُولُ ‏ ‏قَدْنِي ‏ ‏قَدْنِي ‏ ‏وَأَمَّا الْجَنَّةُ فَيَبْقَى فِيهَا أَهْلُهَا مَا شَاءَ اللَّهُ أَنْ يَبْقَى فَيُنْشِئُ اللَّهُ لَهَا خَلْقًا مَا يَشَاءُ ‏","","",""],[10677,10677,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْوَنُ أَهْلِ النَّارِ عَذَابًا رَجُلٌ فِي رِجْلَيْهِ نَعْلَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ وَمِنْهُمْ فِي النَّارِ إِلَى كَعْبَيْهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ فِي النَّارِ إِلَى رُكْبَتَيْهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ ‏ ‏اغْتُمِرَ ‏ ‏فِي النَّارِ إِلَى ‏ ‏أَرْنَبَتِهِ ‏ ‏مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ هُوَ فِي النَّارِ إِلَى صَدْرِهِ مَعَ إِجْرَاءِ الْعَذَابِ وَمِنْهُمْ مَنْ قَدْ ‏ ‏اغْتُمِرَ ‏ ‏فِي النَّارِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَعَ إِجْرَاءِ الْعَذَابِ قَدْ ‏ ‏اغْتُمِرَ ‏","","",""],[10678,10678,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سَعْدٍ أَبِي الْمُجَاهِدِ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أُرَاهُ قَدْ رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا مُؤْمِنٍ سَقَى مُؤْمِنًا شَرْبَةً عَلَى ظَمَإٍ سَقَاهُ اللَّهُ يَوْمَ الْقِيَامَةِ مِنْ الرَّحِيقِ الْمَخْتُومِ ‏ ‏وَأَيُّمَا مُؤْمِنٍ أَطْعَمَ مُؤْمِنًا عَلَى جُوعٍ أَطْعَمَهُ اللَّهُ مِنْ ثِمَارِ الْجَنَّةِ وَأَيُّمَا مُؤْمِنٍ كَسَا مُؤْمِنًا ثَوْبًا عَلَى عُرْيٍ كَسَاهُ اللَّهُ مِنْ خُضْرِ الْجَنَّةِ ‏","","",""],[10679,10679,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي فَقَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏ثَلَاثَةٌ مَنْ قَالَهُنَّ دَخَلَ الْجَنَّةَ قُلْتُ مَا هُنَّ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا ثُمَّ قَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَالرَّابِعَةُ لَهَا مِنْ الْفَضْلِ كَمَا بَيْنَ السَّمَاءِ إِلَى الْأَرْضِ وَهِيَ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏","","",""],[10680,10680,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏يَدْعُو هَكَذَا وَجَعَلَ بَاطِنَ كَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[10681,10681,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْرَائِيلَ يَعْنِي إِسْمَاعِيلَ بْنَ أَبِي إِسْحَاقَ الْمُلَائِيَّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي تَارِكٌ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ كِتَابُ اللَّهِ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي وَإِنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ ‏","","",""],[10682,10682,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْفَزَارِيُّ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ الْهِجْرَةِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنَّ الْهِجْرَةَ شَأْنُهَا شَدِيدٌ فَهَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ هَلْ تُؤَدِّي صَدَقَتَهَا قَالَ نَعَمْ قَالَ هَلْ ‏ ‏تَمْنَحُ ‏ ‏مِنْهَا قَالَ نَعَمْ قَالَ هَلْ تَحْلِبُهَا يَوْمَ ‏ ‏وِرْدِهَا ‏ ‏قَالَ نَعَمْ قَالَ فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا ‏","","",""],[10683,10683,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَدَّمَ ثَلَاثَةً مِنْ وَلَدِهِ حَجَبُوهُ مِنْ النَّارِ ‏","","",""],[10684,10684,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَعْدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ خَمْسٍ مُدْمِنُ خَمْرٍ وَلَا مُؤْمِنٌ بِسِحْرٍ وَلَا قَاطِعُ ‏ ‏رَحِمٍ ‏ ‏وَلَا ‏ ‏كَاهِنٌ ‏ ‏وَلَا ‏ ‏مَنَّانٌ ‏","","",""],[10685,10685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ أَعْرَابِيًّا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْهِجْرَةِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنَّ الْهِجْرَةَ شَأْنُهَا شَدِيدٌ فَهَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ أَلَسْتَ تُؤَدِّي صَدَقَتَهَا قَالَ بَلَى قَالَ أَلَسْتَ ‏ ‏تَمْنَحُ ‏ ‏مِنْهَا قَالَ بَلَى قَالَ أَلَسْتَ تَحْلُبُهَا يَوْمَ ‏ ‏وِرْدِهَا ‏ ‏قَالَ بَلَى قَالَ فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ مَا شِئْتَ فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا ‏","","",""],[10686,10686,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا النَّجِيبِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَجُلًا قَدِمَ مِنْ ‏ ‏نَجْرَانَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ خَاتَمُ ذَهَبٍ فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَسْأَلْهُ عَنْ شَيْءٍ فَرَجَعَ الرَّجُلُ إِلَى امْرَأَتِهِ فَحَدَّثَهَا فَقَالَتْ إِنَّ لَكَ لَشَأْنًا فَارْجِعْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَ إِلَيْهِ فَأَلْقَى خَاتَمَهُ وَجُبَّةً كَانَتْ عَلَيْهِ فَلَمَّا اسْتَأْذَنَ أُذِنَ لَهُ وَسَلَّمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَدَّ عَلَيْهِ السَّلَامَ فَقَالَ يَا رَسُولَ اللَّهِ أَعْرَضْتَ عَنِّي قَبْلُ حِينَ جِئْتُكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ جِئْتَنِي وَفِي يَدِكَ جَمْرَةٌ مِنْ نَارٍ فَقَالَ يَا رَسُولَ اللَّهِ لَقَدْ جِئْتُ إِذًا بِجَمْرٍ كَثِيرٍ وَكَانَ قَدْ قَدِمَ بِحُلِيٍّ مِنْ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَا جِئْتَ بِهِ غَيْرُ مُغْنٍ عَنَّا شَيْئًا إِلَّا مَا أَغْنَتْ حِجَارَةُ ‏ ‏الْحَرَّةِ ‏ ‏وَلَكِنَّهُ مَتَاعُ الْحَيَاةِ الدُّنْيَا فَقَالَ الرَّجُلُ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏اعْذُرْنِي ‏ ‏فِي أَصْحَابِكَ لَا يَظُنُّونَ أَنَّكَ سَخِطْتَ عَلَيَّ بِشَيْءٍ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَذَرَهُ ‏ ‏وَأَخْبَرَ أَنَّ الَّذِي ‏ ‏كَانَ مِنْهُ إِنَّمَا كَانَ لِخَاتَمِهِ الذَّهَبِ ‏","","",""],[10687,10687,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَى ‏ ‏بَنِي لَحْيَانَ ‏ ‏لِيَخْرُجْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ ثُمَّ قَالَ لِلْقَاعِدِ ‏ ‏أَيُّكُمْ خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ ‏","","",""],[10688,10688,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏حَنَشِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَيْسَ مَرْفُوعًا ‏ ‏قَالَ ‏ ‏لَا يَصْلُحُ ‏ ‏السَّلَفُ ‏ ‏فِي الْقَمْحِ وَالشَّعِيرِ ‏ ‏وَالسُّلْتِ ‏ ‏حَتَّى يُفْرَكَ وَلَا فِي الْعِنَبِ وَالزَّيْتُونِ وَأَشْبَاهِ ذَلِكَ حَتَّى ‏ ‏يُمَجِّجَ ‏ ‏وَلَا ذَهَبًا عَيْنًا ‏ ‏بِوَرِقٍ ‏ ‏دَيْنًا وَلَا ‏ ‏وَرِقًا ‏ ‏دَيْنًا بِذَهَبٍ عَيْنًا ‏","","",""],[10689,10689,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فِي الْمَسْجِدِ ثُمَّ رَجَعَ إِلَى بَيْتِهِ حِينَئِذٍ فَلْيُصَلِّ فِي بَيْتِهِ رَكْعَتَيْنِ وَلْيَجْعَلْ فِي بَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ فَإِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا ‏","","",""],[10690,10690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْهَيْثَمِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ بَيَاضَ ‏ ‏كَشْحِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ ‏","","",""],[10691,10691,"","","‏ ‏حَدَّثَنَاه ‏ ‏مُوسَى هُوَ ابْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ ‏ ‏كَشْحِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ ‏","","",""],[10692,10692,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَاتَ ‏ ‏قَتَادَةُ بْنُ النُّعْمَانِ ‏ ‏يَقْرَأُ اللَّيْلَ كُلَّهُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَتَعْدِلُ نِصْفَ الْقُرْآنِ ‏ ‏أَوْ ثُلُثَهُ ‏","","",""],[10693,10693,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي ثَوْبٍ فَلْيَجْعَلْ طَرَفَهُ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[10694,10694,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَشْهَدُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَهُ عَنْ ذَلِكَ وَزَجَرَهُ أَنْ يَسْتَقْبِلَ الْقِبْلَةَ لِبَوْلٍ ‏ ‏وَهَذَا يَتْلُو حَدِيثَ ‏ ‏ابْنِ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يَشْرَبُ وَهُوَ قَائِمٌ فَقَالَ كُنَّا نَكْرَهُ ذَاكَ ‏ ‏ثُمَّ ذَكَرَ حَدِيثَ ‏ ‏أَبِي سَعِيدٍ ‏","","",""],[10695,10695,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ مَطَرٍ الْحَبَطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رُؤْبَةَ شَدَّادُ بْنُ عِمْرَانَ الْقَيْسِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي مَرَرْتُ بِوَادِي كَذَا وَكَذَا فَإِذَا رَجُلٌ مُتَخَشِّعٌ حَسَنُ الْهَيْئَةِ ‏ ‏يُصَلِّي فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ إِلَيْهِ فَاقْتُلْهُ قَالَ فَذَهَبَ إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَلَمَّا رَآهُ عَلَى تِلْكَ الْحَالِ كَرِهَ أَنْ يَقْتُلَهُ فَرَجَعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعُمَرَ ‏ ‏اذْهَبْ فَاقْتُلْهُ فَذَهَبَ ‏ ‏عُمَرُ ‏ ‏فَرَآهُ عَلَى تِلْكَ الْحَالِ الَّتِي رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ فَكَرِهَ أَنْ يَقْتُلَهُ قَالَ فَرَجَعَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي رَأَيْتُهُ ‏ ‏يُصَلِّي مُتَخَشِّعًا فَكَرِهْتُ أَنْ أَقْتُلَهُ قَالَ يَا ‏ ‏عَلِيُّ ‏ ‏اذْهَبْ فَاقْتُلْهُ قَالَ فَذَهَبَ ‏ ‏عَلِيٌّ ‏ ‏فَلَمْ يَرَهُ فَرَجَعَ ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُ لَمْ ‏ ‏يُرَهْ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَعُودُونَ فِيهِ حَتَّى يَعُودَ السَّهْمُ فِي ‏ ‏فُوقِهِ ‏ ‏فَاقْتُلُوهُمْ هُمْ شَرُّ ‏ ‏الْبَرِيَّةِ ‏","","",""],[10696,10696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي نَوْفٍ ‏ ‏عَنِ ‏ ‏سَلِيطِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَتَوَضَّأُ مِنْ ‏ ‏بِئْرِ بُضَاعَةَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏تَوَضَّأُ مِنْهَا وَهِيَ يُلْقَى فِيهَا مَا يُلْقَى مِنْ النَّتْنِ فَقَالَ إِنَّ ‏ ‏الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ ‏","","",""],[10697,10697,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ قَالُوا يَا رَسُولَ اللَّهِ نَرَى رَبَّنَا قَالَ فَقَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الشَّمْسِ نِصْفَ النَّهَارِ قَالُوا لَا قَالَ فَتُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالُوا لَا قَالَ فَإِنَّكُمْ لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ إِلَّا كَمَا ‏ ‏تُضَارُّونَ ‏ ‏فِي ذَلِكَ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏لَا ‏ ‏تُضَارُّونَ ‏ ‏يَقُولُ لَا ‏ ‏تُمَارُونَ ‏","","",""],[10698,10698,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الصَّفُّ الْمُقَدَّمُ وَشَرُّهَا الصَّفُّ الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّهَا الْمُقَدَّمُ وَقَالَ يَا مَعْشَرَ النِّسَاءِ لَا تَرْفَعْنَ رُءُوسَكُنَّ إِذَا سَجَدْتُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏","","",""],[10699,10699,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ الْمِقْدَامِ ‏ ‏وَحُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عِصْمَةَ الْعِجْلِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏فَهَزَّهَا ثُمَّ قَالَ ‏ ‏مَنْ يَأْخُذُهَا بِحَقِّهَا فَجَاءَ فُلَانٌ فَقَالَ أَنَا قَالَ ‏ ‏أَمِطْ ‏ ‏ثُمَّ جَاءَ رَجُلٌ فَقَالَ ‏ ‏أَمِطْ ‏ ‏ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي كَرَّمَ وَجْهَ ‏ ‏مُحَمَّدٍ ‏ ‏لَأُعْطِيَنَّهَا رَجُلًا لَا يَفِرُّ ‏ ‏هَاكَ يَا ‏ ‏عَلِيُّ ‏ ‏فَانْطَلَقَ حَتَّى فَتَحَ اللَّهُ عَلَيْهِ ‏ ‏خَيْبَرَ ‏ ‏وَفَدَكَ ‏ ‏وَجَاءَ بِعَجْوَتِهِمَا ‏ ‏وَقَدِيدِهِمَا ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏بِعَجْوَتِهَا ‏ ‏وَقَدِيدِهَا ‏","","",""],[10700,10700,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ سَمِعْتُ فُلَانًا يَقُولُ خَيْرًا ذَكَرَ أَنَّكَ أَعْطَيْتَهُ دِينَارَيْنِ قَالَ لَكِنْ فُلَانٌ لَا يَقُولُ ذَلِكَ وَلَا ‏ ‏يُثْنِي ‏ ‏بِهِ لَقَدْ أَعْطَيْتُهُ مَا بَيْنَ الْعَشَرَةِ إِلَى الْمِائَةِ ‏ ‏أَوْ قَالَ إِلَى الْمِائَتَيْنِ ‏ ‏وَإِنَّ أَحَدَهُمْ لَيَسْأَلُنِي الْمَسْأَلَةَ فَأُعْطِيهَا إِيَّاهُ فَيَخْرُجُ بِهَا مُتَأَبِّطُهَا وَمَا هِيَ لَهُمْ إِلَّا نَارٌ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ فَلِمَ ‏ ‏تُعْطِيهِمْ قَالَ ‏ ‏إِنَّهُمْ يَأْبَوْنَ إِلَّا أَنْ يَسْأَلُونِي ‏ ‏وَيَأْبَى اللَّهُ لِي الْبُخْلَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[10701,10701,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُئِلَ أَيُّ النَّاسِ خَيْرٌ فَقَالَ ‏ ‏مُؤْمِنٌ مُجَاهِدٌ بِمَالِهِ وَنَفْسِهِ فِي سَبِيلِ اللَّهِ قَالَ ثُمَّ مَنْ قَالَ مُؤْمِنٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏","","",""],[10702,10702,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ ‏ ‏زُمْرَةٍ ‏ ‏تَدْخُلُ الْجَنَّةَ يَوْمَ الْقِيَامَةِ صُورَةُ وُجُوهِهِمْ عَلَى مِثْلِ صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ ‏ ‏وَالزُّمْرَةُ ‏ ‏الثَّانِيَةُ عَلَى لَوْنٍ أَحْسَنَ مِنْ كَوْكَبٍ ‏ ‏دُرِّيٍّ ‏ ‏فِي السَّمَاءِ لِكُلِّ رَجُلٍ مِنْهُمْ زَوْجَتَانِ عَلَى كُلِّ زَوْجَةٍ سَبْعُونَ ‏ ‏حُلَّةً ‏ ‏يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ لُحُومِهَا وَدَمِهَا وَحُلَلِهَا ‏","","",""],[10703,10703,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ فَقَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالَ قُلْنَا لَا قَالَ فَهَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ قَالَ قُلْنَا لَا قَالَ فَإِنَّكُمْ تَرَوْنَ رَبَّكُمْ كَذَلِكَ يَوْمَ الْقِيَامَةِ يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ قَالَ فَيُقَالُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتْبَعْهُ قَالَ فَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الشَّمْسَ الشَّمْسَ فَيَتَسَاقَطُونَ فِي النَّارِ وَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الْقَمَرَ الْقَمَرَ فَيَتَسَاقَطُونَ فِي النَّارِ وَيَتْبَعُ الَّذِينَ كَانُوا يَعْبُدُونَ الْأَوْثَانَ الْأَوْثَانَ وَالَّذِينَ كَانُوا يَعْبُدُونَ الْأَصْنَامَ الْأَصْنَامَ فَيَتَسَاقَطُونَ فِي النَّارِ قَالَ وَكُلُّ مَنْ كَانَ يُعْبَدُ مِنْ ‏ ‏دُونِ اللَّهِ حَتَّى يَتَسَاقَطُونَ فِي النَّارِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْقَى الْمُؤْمِنُونَ وَمُنَافِقُوهُمْ بَيْنَ ظَهْرَيْهِمْ وَبَقَايَا ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏وَقَلَّلَهُمْ بِيَدِهِ قَالَ ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فَيَقُولُ ‏ ‏أَلَا تَتَّبِعُونَ مَا كُنْتُمْ تَعْبُدُونَ قَالَ فَيَقُولُونَ كُنَّا نَعْبُدُ اللَّهَ وَلَمْ نَرَ اللَّهَ فَيُكْشَفُ عَنْ سَاقٍ فَلَا يَبْقَى أَحَدٌ كَانَ يَسْجُدُ لِلَّهِ إِلَّا وَقَعَ سَاجِدًا وَلَا يَبْقَى أَحَدٌ كَانَ يَسْجُدُ ‏ ‏رِيَاءً ‏ ‏وَسُمْعَةً ‏ ‏إِلَّا وَقَعَ عَلَى قَفَاهُ قَالَ ثُمَّ يُوضَعُ ‏ ‏الصِّرَاطُ ‏ ‏بَيْنَ ظَهْرَيْ جَهَنَّمَ وَالْأَنْبِيَاءُ بِنَاحِيتَيْهِ قَوْلُهُمْ اللَّهُمَّ سَلِّمْ سَلِّمْ اللَّهُمَّ سَلِّمْ سَلِّمْ وَإِنَّهُ ‏ ‏لَدَحْضُ ‏ ‏مَزَلَّةٍ ‏ ‏وَإِنَّهُ ‏ ‏لَكَلَالِيبُ ‏ ‏وَخَطَاطِيفُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَلَا أَدْرِي لَعَلَّهُ قَدْ قَالَ تَخْطَفُ النَّاسَ ‏ ‏وَحَسَكَةٌ ‏ ‏تَنْبُتُ ‏ ‏بِنَجْدٍ ‏ ‏يُقَالُ لَهَا ‏ ‏السَّعْدَانُ ‏ ‏قَالَ ‏ ‏وَنَعَتَهَا ‏ ‏لَهُمْ قَالَ فَأَكُونُ أَنَا وَأُمَّتِي لَأَوَّلَ مَنْ مَرَّ ‏ ‏أَوْ أَوَّلَ مَنْ ‏ ‏يُجِيزُ ‏ ‏قَالَ فَيَمُرُّونَ عَلَيْهِ مِثْلَ الْبَرْقِ وَمِثْلَ الرِّيحِ وَمِثْلَ ‏ ‏أَجَاوِيدِ ‏ ‏الْخَيْلِ وَالرِّكَابِ فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ ‏ ‏مُكَلَّمٌ ‏ ‏وَمَكْدُوسٌ ‏ ‏فِي النَّارِ فَإِذَا قَطَعُوهُ ‏ ‏أَوْ فَإِذَا جَاوَزُوهُ ‏ ‏فَمَا أَحَدُكُمْ فِي حَقٍّ يَعْلَمُ أَنَّهُ حَقٌّ لَهُ بِأَشَدَّ مُنَاشَدَةً مِنْهُمْ فِي إِخْوَانِهِمْ الَّذِينَ سَقَطُوا فِي النَّارِ يَقُولُونَ أَيْ رَبِّ كُنَّا نَغْزُو جَمِيعًا وَنَحُجُّ جَمِيعًا وَنَعْتَمِرُ جَمِيعًا فَبِمَ نَجَوْنَا الْيَوْمَ وَهَلَكُوا قَالَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ انْظُرُوا مَنْ كَانَ فِي قَلْبِهِ زِنَةُ دِينَارٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ قَالَ ثُمَّ يَقُولُ مَنْ كَانَ فِي قَلْبِهِ زِنَةُ ‏ ‏قِيرَاطٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ قَالَ ثُمَّ يَقُولُ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ ‏ ‏قَالَ ثُمَّ يَقُولُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏بَيْنِي وَبَيْنَكُمْ كِتَابُ اللَّهِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَظُنُّهُ ‏ ‏يَعْنِي قَوْلَهُ ‏ { ‏وَإِنْ كَانَ ‏ ‏مِثْقَالَ ‏ ‏حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ ‏} ‏قَالَ فَيُخْرَجُونَ ‏ ‏مِنْ النَّارِ فَيُطْرَحُونَ فِي نَهَرٍ يُقَالُ لَهُ نَهَرُ الْحَيَوَانِ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبُّ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ أَلَا تَرَوْنَ مَا يَكُونُ مِنْ النَّبْتِ إِلَى الشَّمْسِ يَكُونُ أَخْضَرَ وَمَا يَكُونُ إِلَى الظِّلِّ يَكُونُ أَصْفَرَ قَالُوا يَا رَسُولَ اللَّهِ كَأَنَّكَ كُنْتَ قَدْ رَعَيْتَ الْغَنَمَ قَالَ أَجَلْ قَدْ رَعَيْتُ الْغَنَمَ ‏","","",""],[10704,10704,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏فِرَاسُ بْنُ يَحْيَى الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَقَدْ دَخَلَ رَجُلٌ الْجَنَّةَ مَا عَمِلَ خَيْرًا قَطُّ قَالَ لِأَهْلِهِ حِينَ حَضَرَهُ الْمَوْتُ إِذَا أَنَا مُتُّ فَأَحْرِقُونِي ثُمَّ اسْحَقُونِي ثُمَّ اذْرُوا نِصْفِي فِي الْبَحْرِ وَنِصْفِي فِي الْبَرِّ فَأَمَرَ اللَّهُ الْبَرَّ وَالْبَحْرَ فَجَمَعَاهُ ثُمَّ قَالَ ‏ ‏مَا حَمَلَكَ عَلَى مَا فَعَلْتَ قَالَ مَخَافَتُكَ قَالَ فَغُفِرَ لَهُ لِذَلِكَ ‏","","",""],[10705,10705,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُلُوبُ أَرْبَعَةٌ قَلْبٌ ‏ ‏أَجْرَدُ ‏ ‏فِيهِ مِثْلُ ‏ ‏السِّرَاجِ ‏ ‏يُزْهِرُ وَقَلْبٌ ‏ ‏أَغْلَفُ ‏ ‏مَرْبُوطٌ عَلَى غِلَافِهِ وَقَلْبٌ ‏ ‏مَنْكُوسٌ ‏ ‏وَقَلْبٌ ‏ ‏مُصْفَحٌ ‏ ‏فَأَمَّا الْقَلْبُ ‏ ‏الْأَجْرَدُ ‏ ‏فَقَلْبُ الْمُؤْمِنِ ‏ ‏سِرَاجُهُ ‏ ‏فِيهِ نُورُهُ وَأَمَّا الْقَلْبُ ‏ ‏الْأَغْلَفُ ‏ ‏فَقَلْبُ الْكَافِرِ وَأَمَّا الْقَلْبُ ‏ ‏الْمَنْكُوسُ ‏ ‏فَقَلْبُ الْمُنَافِقِ عَرَفَ ثُمَّ أَنْكَرَ وَأَمَّا الْقَلْبُ ‏ ‏الْمُصْفَحُ ‏ ‏فَقَلْبٌ فِيهِ إِيمَانٌ وَنِفَاقٌ فَمَثَلُ الْإِيمَانِ فِيهِ كَمَثَلِ ‏ ‏الْبَقْلَةِ ‏ ‏يَمُدُّهَا الْمَاءُ الطَّيِّبُ وَمَثَلُ النِّفَاقِ فِيهِ كَمَثَلِ الْقُرْحَةِ يَمُدُّهَا الْقَيْحُ وَالدَّمُ فَأَيُّ الْمَدَّتَيْنِ غَلَبَتْ عَلَى الْأُخْرَى غَلَبَتْ عَلَيْهِ ‏","","",""],[10706,10706,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَطَرِ بْنِ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَمْلِكَ رَجُلٌ مِنْ أَهْلِ بَيْتِي أَجْلَى ‏ ‏أَقْنَى ‏ ‏يَمْلَأُ الْأَرْضَ عَدْلًا كَمَا مُلِئَتْ قَبْلَهُ ظُلْمًا يَكُونُ سَبْعَ سِنِينَ ‏","","",""],[10707,10707,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ طَلْحَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي ‏ ‏أُوشِكُ ‏ ‏أَنْ ‏ ‏أُدْعَى فَأُجِيبَ وَإِنِّي تَارِكٌ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏كِتَابَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَعِتْرَتِي ‏ ‏كِتَابُ اللَّهِ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي وَإِنَّ اللَّطِيفَ الْخَبِيرَ أَخْبَرَنِي أَنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ فَانْظُرُونِي بِمَ تَخْلُفُونِي فِيهِمَا ‏","","",""],[10708,10708,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَرَزَ بَيْنَ يَدَيْهِ غَرْزًا ثُمَّ غَرَزَ إِلَى جَنْبِهِ آخَرَ ثُمَّ غَرَزَ الثَّالِثَ فَأَبْعَدَهُ ثُمَّ قَالَ هَلْ تَدْرُونَ مَا هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هَذَا الْإِنْسَانُ وَهَذَا أَجَلُهُ وَهَذَا أَمَلُهُ ‏ ‏يَتَعَاطَى الْأَمَلَ وَالْأَجَلُ ‏ ‏يَخْتَلِجُهُ ‏ ‏دُونَ ذَلِكَ ‏","","",""],[10709,10709,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ وَلَا قَطِيعَةُ رَحِمٍ إِلَّا أَعْطَاهُ اللَّهُ بِهَا إِحْدَى ثَلَاثٍ إِمَّا أَنْ تُعَجَّلَ لَهُ دَعْوَتُهُ وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الْآخِرَةِ وَإِمَّا أَنْ يَصْرِفَ عَنْهُ مِنْ السُّوءِ مِثْلَهَا قَالُوا إِذًا نُكْثِرُ قَالَ اللَّهُ أَكْثَرُ ‏","","",""],[10710,10710,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ قَالَ فَاخْتَارَ ذَلِكَ الْعَبْدُ مَا عِنْدَ اللَّهِ قَالَ فَبَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَعَجِبْنَا لِبُكَائِهِ أَنْ خَبَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَبْدٍ خُيِّرَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَيَّرَ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَعْلَمَنَا بِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَمَنَّ ‏ ‏النَّاسِ عَلَيَّ فِي صُحْبَتِهِ وَمَالِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا مِنْ النَّاسِ خَلِيلًا غَيْرَ رَبِّي لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَلَكِنْ أُخُوَّةُ الْإِسْلَامِ ‏ ‏أَوْ مَوَدَّتُهُ ‏ ‏لَا ‏ ‏يَبْقَى بَابٌ فِي الْمَسْجِدِ إِلَّا سُدَّ إِلَّا بَابَ ‏ ‏أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏وَبُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَاه ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[10711,10711,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِي ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏أُخْبِرَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏بِجِنَازَةٍ فَعَادَ تَخَلَّفَ حَتَّى إِذَا أَخَذَ النَّاسُ مَجَالِسَهُمْ ثُمَّ جَاءَ فَلَمَّا رَآهُ الْقَوْمُ ‏ ‏تَشَذَّبُوا ‏ ‏عَنْهُ فَقَامَ بَعْضُهُمْ لِيَجْلِسَ فِي مَجْلِسِهِ فَقَالَ لَا إِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ خَيْرَ الْمَجَالِسِ أَوْسَعُهَا ثُمَّ ‏ ‏تَنَحَّى ‏ ‏وَجَلَسَ فِي مَجْلِسٍ وَاسِعٍ ‏","","",""],[10712,10712,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ مَا بَالُ رِجَالٍ يَقُولُونَ إِنَّ رَحِمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَنْفَعُ قَوْمَهُ بَلَى وَاللَّهِ ‏ ‏إِنَّ رَحِمِي مَوْصُولَةٌ فِي الدُّنْيَا وَالْآخِرَةِ وَإِنِّي أَيُّهَا النَّاسُ ‏ ‏فَرَطٌ ‏ ‏لَكُمْ عَلَى الْحَوْضِ فَإِذَا جِئْتُمْ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا فُلَانُ بْنُ فُلَانٍ وَقَالَ أَخُوهُ أَنَا فُلَانُ بْنُ فُلَانٍ قَالَ لَهُمْ أَمَّا النَّسَبُ فَقَدْ عَرَفْتُهُ وَلَكِنَّكُمْ أَحْدَثْتُمْ بَعْدِي وَارْتَدَدْتُمْ ‏ ‏الْقَهْقَرَى ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[10713,10713,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏اشْتَكَى ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَوْ غَابَ ‏ ‏فَصَلَّى بِنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَجَهَرَ بِالتَّكْبِيرِ حِينَ افْتَتَحَ الصَّلَاةَ وَحِينَ رَكَعَ وَحِينَ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَحِينَ رَفَعَ رَأْسَهُ مِنْ السُّجُودِ وَحِينَ سَجَدَ وَحِينَ قَامَ بَيْنَ الرَّكْعَتَيْنِ حَتَّى قَضَى صَلَاتَهُ عَلَى ذَلِكَ فَلَمَّا صَلَّى قِيلَ لَهُ قَدْ اخْتَلَفَ النَّاسُ عَلَى صَلَاتِكَ فَخَرَجَ فَقَامَ عِنْدَ الْمِنْبَرِ فَقَالَ أَيُّهَا النَّاسُ وَاللَّهِ مَا أُبَالِي ‏ ‏اخْتَلَفَتْ صَلَاتُكُمْ أَوْ لَمْ تَخْتَلِفْ هَكَذَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏","","",""],[10714,10714,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يُصِيبُ الْمَرْءَ الْمُسْلِمَ مِنْ ‏ ‏نَصَبٍ ‏ ‏وَلَا ‏ ‏وَصَبٍ ‏ ‏وَلَا هَمٍّ وَلَا حَزَنٍ وَلَا غَمٍّ وَلَا أَذًى حَتَّى الشَّوْكَةَ ‏ ‏يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ عَزَّ وَجَلَّ بِهَا مِنْ خَطَايَاهُ ‏","","",""],[10715,10715,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ الْعُطَارِدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتَمُّوا بِي يَأْتَمُّ بِكُمْ مَنْ بَعْدَكُمْ فَإِنَّهُ لَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمْ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[10716,10716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً بَعْدَ الْعَصْرِ إِلَى ‏ ‏مُغَيْرِبَانِ الشَّمْسِ حَفِظَهَا مِنَّا مَنْ حَفِظَهَا وَنَسِيَهَا مِنَّا مَنْ نَسِيَهَا فَحَمِدَ اللَّهَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏وَأَكْثَرُ حِفْظِي أَنَّهُ قَالَ بِمَا هُوَ كَائِنٌ إِلَى يَوْمِ الْقِيَامَةِ فَحَمِدَ اللَّهَ ‏ ‏وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَإِنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا فَنَاظِرٌ كَيْفَ تَعْمَلُونَ أَلَا فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ أَلَا إِنَّ بَنِي ‏ ‏آدَمَ ‏ ‏خُلِقُوا عَلَى طَبَقَاتٍ شَتَّى مِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا ‏ ‏وَيَحْيَا مُؤْمِنًا وَيَمُوتُ مُؤْمِنًا وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا ‏ ‏وَيَحْيَا كَافِرًا وَيَمُوتُ كَافِرًا وَمِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا ‏ ‏وَيَحْيَا مُؤْمِنًا وَيَمُوتُ كَافِرًا وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا ‏ ‏وَيَحْيَا كَافِرًا وَيَمُوتُ مُؤْمِنًا أَلَا إِنَّ الْغَضَبَ جَمْرَةٌ تُوقَدُ فِي جَوْفِ ابْنِ ‏ ‏آدَمَ ‏ ‏أَلَا تَرَوْنَ إِلَى حُمْرَةِ عَيْنَيْهِ وَانْتِفَاخِ ‏ ‏أَوْدَاجِهِ ‏ ‏فَإِذَا وَجَدَ أَحَدُكُمْ شَيْئًا مِنْ ذَلِكَ فَالْأَرْضَ الْأَرْضَ أَلَا إِنَّ خَيْرَ الرِّجَالِ مَنْ كَانَ بَطِيءَ الْغَضَبِ سَرِيعَ الرِّضَا وَشَرَّ الرِّجَالِ مَنْ كَانَ سَرِيعَ الْغَضَبِ بَطِيءَ الرِّضَا فَإِذَا كَانَ الرَّجُلُ بَطِيءَ الْغَضَبِ بَطِيءَ ‏ ‏الْفَيْءِ ‏ ‏وَسَرِيعَ الْغَضَبِ وَسَرِيعَ ‏ ‏الْفَيْءِ ‏ ‏فَإِنَّهَا بِهَا أَلَا إِنَّ خَيْرَ التُّجَّارِ مَنْ كَانَ حَسَنَ ‏ ‏الْقَضَاءِ ‏ ‏حَسَنَ الطَّلَبِ وَشَرَّ التُّجَّارِ مَنْ كَانَ سَيِّئَ ‏ ‏الْقَضَاءِ ‏ ‏سَيِّئَ الطَّلَبِ فَإِذَا كَانَ الرَّجُلُ حَسَنَ ‏ ‏الْقَضَاءِ ‏ ‏سَيِّئَ الطَّلَبِ أَوْ كَانَ سَيِّئَ ‏ ‏الْقَضَاءِ ‏ ‏حَسَنَ الطَّلَبِ فَإِنَّهَا بِهَا أَلَا إِنَّ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏أَلَا وَأَكْبَرُ ‏ ‏الْغَدْرِ ‏ ‏غَدْرُ ‏ ‏أَمِيرِ عَامَّةٍ أَلَا لَا يَمْنَعَنَّ رَجُلًا ‏ ‏مَهَابَةُ ‏ ‏النَّاسِ أَنْ يَتَكَلَّمَ بِالْحَقِّ إِذَا عَلِمَهُ أَلَا إِنَّ أَفْضَلَ الْجِهَادِ كَلِمَةُ حَقٍّ عِنْدَ سُلْطَانٍ ‏ ‏جَائِرٍ ‏ ‏فَلَمَّا كَانَ عِنْدَ ‏ ‏مُغَيْرِبَانِ الشَّمْسِ قَالَ أَلَا إِنَّ مِثْلَ مَا بَقِيَ مِنْ الدُّنْيَا فِيمَا مَضَى مِنْهَا مِثْلُ مَا بَقِيَ مِنْ يَوْمِكُمْ هَذَا فِيمَا مَضَى مِنْهُ ‏","","",""],[10717,10717,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ ‏ ‏مَضَبَّةٍ ‏ ‏فَمَا تَأْمُرُنَا قَالَ ‏ ‏بَلَغَنِي أَنَّ أُمَّةً مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُسِخَتْ ‏ ‏دَوَابَّ فَمَا أَدْرِي أَيُّ الدَّوَابِّ هِيَ فَلَمْ يَأْمُرْ وَلَمْ يَنْهَ ‏","","",""],[10718,10718,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو مُوسَى ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏ثَلَاثًا فَلَمْ يَأْذَنْ لَهُ ‏ ‏عُمَرُ ‏ ‏فَرَجَعَ فَلَقِيَهُ ‏ ‏عُمَرُ ‏ ‏فَقَالَ مَا شَأْنُكَ رَجَعْتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ قَالَ لَتَأْتِيَنَّ عَلَى هَذَا ‏ ‏بِبَيِّنَةٍ ‏ ‏أَوْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ فَأَتَى مَجْلِسَ قَوْمِهِ ‏ ‏فَنَاشَدَهُمْ ‏ ‏اللَّهَ عَزَّ وَجَلَّ فَقُلْتُ أَنَا مَعَكَ فَشَهِدُوا لَهُ بِذَلِكَ ‏ ‏فَخَلَّا سَبِيلَهُمْ ‏","","",""],[10719,10719,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أَخِي ‏ ‏اسْتُطْلِقَ ‏ ‏بَطْنُهُ قَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏قَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ اسْقِهِ عَسَلًا قَالَ فَذَهَبَ ثُمَّ جَاءَ فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ لَهُ فِي الرَّابِعَةِ اسْقِهِ عَسَلًا قَالَ ‏ ‏أَظُنُّهُ قَالَ فَسَقَاهُ ‏ ‏فَبَرَأَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّابِعَةِ ‏ ‏صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ ‏","","",""],[10720,10720,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَحَدَّثَ عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ابْنُ أَخِي قَدْ ‏ ‏عَرِبَ ‏ ‏بَطْنُهُ فَقَالَ اسْقِ ابْنَ أَخِيكَ عَسَلًا قَالَ فَسَقَاهُ فَلَمْ يَزِدْهُ إِلَّا شِدَّةً فَرَجَعَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ مَرَّاتٍ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الثَّالِثَةِ اسْقِ ابْنَ أَخِيكَ عَسَلًا ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ صَدَقَ وَكَذَبَ بَطْنُ ابْنِ أَخِيكَ قَالَ فَسَقَاهُ فَعَافَاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[10721,10721,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَدْ أَعْطَى اللَّهُ كُلَّ نَبِيٍّ عَطِيَّةً فَكُلٌّ قَدْ تَعَجَّلَهَا وَإِنِّي أَخَّرْتُ عَطِيَّتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي وَإِنَّ الرَّجُلَ مِنْ أُمَّتِي ‏ ‏لَيَشْفَعُ ‏ ‏لِلْفِئَامِ ‏ ‏مِنْ النَّاسِ فَيَدْخُلُونَ الْجَنَّةَ وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلْقَبِيلَةِ وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلْعُصْبَةِ ‏ ‏وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلثَّلَاثَةِ وَلِلرَّجُلَيْنِ وَلِلرَّجُلِ ‏","","",""],[10722,10722,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْرَمَ وَأَصْحَابُهُ عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏غَيْرَ ‏ ‏عُثْمَانَ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏فَاسْتَغْفَرَ لِلْمُحَلِّقِينَ ثَلَاثًا وَلِلْمُقَصِّرِينَ مَرَّةً ‏","","",""],[10723,10723,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏خَطَبَ ‏ ‏مَرْوَانُ ‏ ‏قَبْلَ الصَّلَاةِ فِي يَوْمِ الْعِيدِ فَقَامَ رَجُلٌ فَقَالَ إِنَّمَا كَانَتْ الصَّلَاةُ قَبْلَ الْخُطْبَةِ فَقَالَ ‏ ‏تَرَى ذَلِكَ يَا أَبَا فُلَانٍ فَقَامَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَقَالَ أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[10724,10724,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ النَّارِ الَّذِينَ لَا يُرِيدُ اللَّهُ عَزَّ وَجَلَّ إِخْرَاجَهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ وَإِنَّ أَهْلَ النَّارِ الَّذِينَ يُرِيدُ اللَّهُ عَزَّ وَجَلَّ إِخْرَاجَهُمْ يُمِيتُهُمْ فِيهَا إِمَاتَةً حَتَّى يَصِيرُوا فَحْمًا ثُمَّ يُخْرَجُونَ ‏ ‏ضَبَائِرَ ‏ ‏فَيُلْقَوْنَ عَلَى أَنْهَارِ الْجَنَّةِ ‏ ‏أَوْ يُرَشُّ عَلَيْهِمْ مِنْ أَنْهَارِ الْجَنَّةِ ‏ ‏فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ ‏","","",""],[10725,10725,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ وَشَيَّعَهَا كَانَ لَهُ ‏ ‏قِيرَاطَانِ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا وَلَمْ يُشَيِّعْهَا كَانَ لَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَالْقِيرَاطُ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10726,10726,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فَخَلَعَ نَعْلَيْهِ فَخَلَعَ النَّاسُ نِعَالَهُمْ فَلَمَّا ‏ ‏انْصَرَفَ ‏ ‏قَالَ لِمَ خَلَعْتُمْ نِعَالَكُمْ فَقَالُوا يَا رَسُولَ اللَّهِ رَأَيْنَاكَ خَلَعْتَ فَخَلَعْنَا قَالَ إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَتَانِي فَأَخْبَرَنِي أَنَّ بِهِمَا خَبَثًا ‏ ‏فَإِذَا جَاءَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقْلِبْ نَعْلَهُ فَلْيَنْظُرْ فِيهَا فَإِنْ رَأَى بِهَا خَبَثًا فَلْيُمِسَّهُ بِالْأَرْضِ ثُمَّ لِيُصَلِّ فِيهِمَا ‏","","",""],[10727,10727,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَا أُحَدِّثُكُمْ إِلَّا مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي ‏ ‏أَنَّ عَبْدًا قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ فَدُلَّ عَلَى رَجُلٍ فَأَتَاهُ فَقَالَ إِنِّي قَتَلْتُ تِسْعَةً وَتِسْعِينَ نَفْسًا فَهَلْ لِي مِنْ تَوْبَةٍ قَالَ بَعْدَ قَتْلِ تِسْعَةٍ وَتِسْعِينَ نَفْسًا قَالَ ‏ ‏فَانْتَضَى ‏ ‏سَيْفَهُ فَقَتَلَهُ بِهِ فَأَكْمَلَ بِهِ مِائَةً ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ فَدُلَّ عَلَى رَجُلٍ فَأَتَاهُ فَقَالَ إِنِّي قَتَلْتُ مِائَةَ نَفْسٍ فَهَلْ لِي مِنْ تَوْبَةٍ فَقَالَ وَمَنْ يَحُولُ بَيْنَكَ وَبَيْنَ التَّوْبَةِ اخْرُجْ مِنْ الْقَرْيَةِ الْخَبِيثَةِ الَّتِي أَنْتَ فِيهَا إِلَى الْقَرْيَةِ الصَّالِحَةِ قَرْيَةِ كَذَا وَكَذَا فَاعْبُدْ رَبَّكَ فِيهَا قَالَ فَخَرَجَ إِلَى الْقَرْيَةِ الصَّالِحَةِ فَعَرَضَ لَهُ أَجَلُهُ فِي الطَّرِيقِ قَالَ فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ الْعَذَابِ قَالَ فَقَالَ إِبْلِيسُ أَنَا أَوْلَى بِهِ إِنَّهُ لَمْ يَعْصِنِي سَاعَةً قَطُّ قَالَ فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ إِنَّهُ خَرَجَ تَائِبًا ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فَحَدَّثَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏فَبَعَثَ اللَّهُ عَزَّ وَجَلَّ لَهُ مَلَكًا ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَيْهِ ثُمَّ رَجَعَ إِلَى حَدِيثِ ‏ ‏قَتَادَةَ ‏ ‏قَالَ فَقَالَ انْظُرُوا أَيُّ الْقَرْيَتَيْنِ كَانَ أَقْرَبَ إِلَيْهِ فَأَلْحِقُوهُ بِأَهْلِهَا ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَحَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏لَمَّا عَرَفَ الْمَوْتَ ‏ ‏احْتَفَزَ ‏ ‏بِنَفْسِهِ فَقَرَّبَ اللَّهُ عَزَّ وَجَلَّ مِنْهُ الْقَرْيَةَ الصَّالِحَةَ وَبَاعَدَ مِنْهُ الْقَرْيَةَ الْخَبِيثَةَ فَأَلْحَقُوهُ بِأَهْلِ الْقَرْيَةِ الصَّالِحَةِ ‏","","",""],[10728,10728,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى حَتَّى نَقُولَ لَا يَدَعُهَا وَيَدَعُهَا حَتَّى نَقُولَ لَا يُصَلِّيهَا ‏","","",""],[10729,10729,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَقُلْتُ ‏ ‏لِفُضَيْلٍ ‏ ‏رَفَعَهُ قَالَ أَحْسِبُهُ قَدْ ‏ ‏رَفَعَهُ قَالَ مَنْ قَالَ حِينَ يَخْرُجُ إِلَى الصَّلَاةِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ وَبِحَقِّ مَمْشَايَ فَإِنِّي لَمْ أَخْرُجْ ‏ ‏أَشَرًا ‏ ‏وَلَا ‏ ‏بَطَرًا ‏ ‏وَلَا ‏ ‏رِيَاءً ‏ ‏وَلَا ‏ ‏سُمْعَةً ‏ ‏خَرَجْتُ اتِّقَاءَ سَخَطِكَ وَابْتِغَاءَ مَرْضَاتِكَ أَسْأَلُكَ أَنْ تُنْقِذَنِي مِنْ النَّارِ وَأَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَكَّلَ اللَّهُ بِهِ سَبْعِينَ أَلْفَ مَلَكٍ يَسْتَغْفِرُونَ لَهُ وَأَقْبَلَ اللَّهُ عَلَيْهِ بِوَجْهِهِ حَتَّى يَفْرَغَ مِنْ صَلَاتِهِ ‏","","",""],[10730,10730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَصَعِدَ الْمِنْبَرَ وَجَلَسْنَا حَوْلَهُ فَقَالَ إِنَّ مِمَّا أَخَافُ عَلَيْكُمْ بَعْدِي مَا يَفْتَحُ اللَّهُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَيْنَا أَنَّهُ يَنْزِلُ عَلَيْهِ ‏ ‏جِبْرِيلُ ‏ ‏فَقِيلَ لَهُ مَا شَأْنُكَ تُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا يُكَلِّمُكَ ‏ ‏فَسُرِّيَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَمْسَحُ عَنْهُ ‏ ‏الرُّحَضَاءَ ‏ ‏فَقَالَ أَيْنَ السَّائِلُ وَكَأَنَّهُ حَمِدَهُ فَقَالَ ‏ ‏إِنَّ الْخَيْرَ لَا يَأْتِي بِالشَّرِّ وَإِنَّ مِمَّا يُنْبِتُ الرَّبِيعُ يَقْتُلُ أَوْ ‏ ‏يُلِمُّ ‏ ‏حَبَطًا ‏ ‏أَلَمْ تَرَ إِلَى آكِلَةِ الْخَضِرَةِ أَكَلَتْ حَتَّى إِذَا ‏ ‏امْتَدَّتْ خَاصِرَتَاهَا ‏ ‏وَاسْتَقْبَلَتْ عَيْنَ الشَّمْسِ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ ‏ ‏رَتَعَتْ ‏ ‏وَإِنَّ الْمَالَ حُلْوَةٌ خَضِرَةٌ وَنِعْمَ صَاحِبُ الْمَرْءِ الْمُسْلِمِ هُوَ لِمَنْ أَعْطَى مِنْهُ الْمِسْكِينَ وَالْيَتِيمَ وَابْنَ السَّبِيلِ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ الَّذِي أَخَذَهُ بِغَيْرِ حَقِّهِ كَمَثَلِ الَّذِي يَأْكُلُ وَلَا يَشْبَعُ فَيَكُونُ عَلَيْهِ شَهِيدًا يَوْمَ الْقِيَامَةِ ‏","","",""],[10731,10731,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا إِلَّا الْقُرْآنَ فَمَنْ كَتَبَ عَنِّي شَيْئًا غَيْرَ الْقُرْآنِ فَلْيَمْحُهُ ‏","","",""],[10732,10732,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتَ عَلَى رَاعِي إِبِلٍ فَنَادِ يَا رَاعِيَ الْإِبِلِ ثَلَاثًا فَإِنْ أَجَابَكَ وَإِلَّا فَاحْلُبْ وَاشْرَبْ مِنْ غَيْرِ أَنْ تُفْسِدَ وَإِذَا أَتَيْتَ عَلَى ‏ ‏حَائِطِ ‏ ‏بُسْتَانٍ فَنَادِ يَا صَاحِبَ ‏ ‏الْحَائِطِ ‏ ‏ثَلَاثًا فَإِنْ أَجَابَكَ وَإِلَّا فَكُلْ ‏","","",""],[10733,10733,"","","‏ ‏و قَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا زَادَ ‏ ‏فَصَدَقَةٌ ‏","","",""],[10734,10734,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَسْعُودٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَمَرَرْنَا بِنَهَرٍ فِيهِ مَاءٌ مِنْ مَاءِ السَّمَاءِ وَالْقَوْمُ صِيَامٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْرَبُوا فَلَمْ يَشْرَبْ أَحَدٌ فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشَرِبَ الْقَوْمُ ‏","","",""],[10735,10735,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا ‏ ‏أَتَى ‏ ‏الرَّجُلُ أَهْلَهُ ثُمَّ أَرَادَ الْعَوْدَ تَوَضَّأَ ‏","","",""],[10736,10736,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَرْسَلَ إِلَيْهِ فَخَرَجَ وَرَأْسُهُ يَقْطُرُ فَقَالَ لَهُ لَعَلَّنَا أَعْجَلْنَاكَ قَالَ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِذَا أُعْجِلْتَ ‏ ‏أَوْ ‏ ‏أُقْحِطْتَ ‏ ‏فَلَا غُسْلَ عَلَيْكَ عَلَيْكَ الْوُضُوءُ ‏","","",""],[10737,10737,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدًا أَبَا الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَشِينَا أَنْ يَكُونَ بَعْدَ نَبِيِّنَا حَدَثٌ فَسَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَخْرُجُ ‏ ‏الْمَهْدِيُّ ‏ ‏فِي أُمَّتِي خَمْسًا ‏ ‏أَوْ سَبْعًا أَوْ تِسْعًا ‏ ‏زَيْدٌ ‏ ‏الشَّاكُّ ‏ ‏قَالَ قُلْتُ أَيُّ شَيْءٍ ‏ ‏قَالَ سِنِينَ ثُمَّ قَالَ يُرْسِلُ السَّمَاءَ عَلَيْهِمْ ‏ ‏مِدْرَارًا ‏ ‏وَلَا ‏ ‏تَدَّخِرُ ‏ ‏الْأَرْضُ مِنْ نَبَاتِهَا شَيْئًا وَيَكُونُ الْمَالُ ‏ ‏كُدُوسًا ‏ ‏قَالَ يَجِيءُ الرَّجُلُ إِلَيْهِ فَيَقُولُ يَا ‏ ‏مَهْدِيُّ ‏ ‏أَعْطِنِي أَعْطِنِي قَالَ ‏ ‏فَيَحْثِي ‏ ‏لَهُ فِي ثَوْبِهِ مَا اسْتَطَاعَ أَنْ يَحْمِلَ ‏","","",""],[10738,10738,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ أَبِي الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نَبِيعُ ‏ ‏أُمَّهَاتِ الْأَوْلَادِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10739,10739,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ أَبِي الْحَوَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الصِّدِّيقِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَتَمَتَّعُ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالثَّوْبِ ‏","","",""],[10740,10740,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ الْفِئَةُ الْبَاغِيَةُ ‏","","",""],[10741,10741,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ السُّورَةُ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ ‏ ‏قَالَ قَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى خَتَمَهَا وَقَالَ النَّاسُ ‏ ‏حَيْزُ ‏ ‏وَأَنَا وَأَصْحَابِي ‏ ‏حَيْزُ ‏ ‏وَقَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مَرْوَانُ ‏ ‏كَذَبْتَ وَعِنْدَهُ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمَا قَاعِدَانِ مَعَهُ عَلَى السَّرِيرِ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏لَوْ شَاءَ هَذَانِ لَحَدَّثَاكَ وَلَكِنْ هَذَا يَخَافُ أَنْ تَنْزِعَهُ عَنْ ‏ ‏عِرَافَةِ ‏ ‏قَوْمِهِ وَهَذَا ‏ ‏يَخْشَى أَنْ تَنْزِعَهُ عَنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَسَكَتَا فَرَفَعَ ‏ ‏مَرْوَانُ ‏ ‏عَلَيْهِ ‏ ‏الدِّرَّةَ ‏ ‏لِيَضْرِبَهُ فَلَمَّا رَأَيَا ذَلِكَ قَالُوا ‏ ‏صَدَقَ ‏","","",""],[10742,10742,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِىَّ ‏ ‏قَالَ ‏ ‏نَزَلَ ‏ ‏أَهْلُ قُرَيْظَةَ ‏ ‏عَلَى حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏سَعْدٍ ‏ ‏فَأَتَاهُ عَلَى حِمَارٍ قَالَ فَلَمَّا ‏ ‏دَنَا ‏ ‏قَرِيبًا مِنْ الْمَسْجِدِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُومُوا إِلَى سَيِّدِكُمْ ‏ ‏أَوْ خَيْرِكُمْ ‏ ‏ثُمَّ قَالَ إِنَّ هَؤُلَاءِ نَزَلُوا عَلَى حُكْمِكَ قَالَ تُقْتَلُ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذَرَارِيُّهُمْ ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ قَضَيْتَ بِحُكْمِ اللَّهِ ‏ ‏وَرُبَّمَا قَالَ قَضَيْتَ بِحُكْمِ الْمَلِكِ ‏","","",""],[10743,10743,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ مُسْتَخْلِفُكُمْ فِيهَا لِيَنْظُرَ كَيْفَ تَعْمَلُونَ فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ فَإِنَّ أَوَّلَ فِتْنَةِ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانَتْ فِي النِّسَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏غُنْدَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏فِي حُكْمِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏إِلَّا أَنَّهُ قَالَ فَإِنِّي أَحْكُمُ أَنْ تُقْتَلَ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذُرِّيَّتُهُمْ ‏ ‏فَقَالَ لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ اللَّهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ الْمَلِكِ ‏ ‏أَوْ الْمَلَكِ شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏عَفَّانُ ‏ ‏قَالَ الْمَلِكُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ جَعْفَرٍ ‏ ‏تُقْتَلُ مُقَاتِلَتُهُمْ ‏ ‏وَتُسْبَى ‏ ‏ذُرِّيَّتُهُمْ ‏ ‏وَقَالَ قَضَيْتَ بِحُكْمِ الْمَلِكِ قَالَ ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ ‏","","",""],[10744,10744,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ ‏ ‏الْعَزْلِ ‏ ‏أَوْ قَالَ فِي ‏ ‏الْعَزْلِ ‏ ‏لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا ذَلِكَ فَإِنَّمَا هُوَ الْقَدَرُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏مَعْبَدٍ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[10745,10745,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَبَّ النَّاسِ إِلَى اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ وَأَقْرَبَهُمْ مِنْهُ مَجْلِسًا إِمَامٌ عَادِلٌ وَإِنَّ أَبْغَضَ النَّاسِ إِلَى اللَّهِ يَوْمَ الْقِيَامَةِ وَأَشَدَّهُ عَذَابًا إِمَامٌ ‏ ‏جَائِرٌ ‏","","",""],[10746,10746,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَمَّنْ ‏ ‏لَقِيَ الْوَفْدَ ‏ ‏وَذَكَرَ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا إِنَّا حَيٌّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ ‏ ‏مُضَرَ ‏ ‏وَلَسْنَا نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلَّا فِي أَشْهُرِ الْحُرُمِ فَمُرْنَا بِأَمْرٍ إِذَا نَحْنُ أَخَذْنَا بِهِ دَخَلْنَا الْجَنَّةَ وَنَأْمُرُ بِهِ ‏ ‏أَوْ ‏ ‏نَدْعُو ‏ ‏مَنْ وَرَاءَنَا فَقَالَ آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ ‏ ‏اعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا فَهَذَا لَيْسَ مِنْ الْأَرْبَعِ وَأَقِيمُوا الصَّلَاةَ وَآتَوْا الزَّكَاةَ وَصُومُوا رَمَضَانَ وَأَعْطُوا مِنْ الْغَنَائِمِ الْخُمُسَ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالُوا وَمَا عِلْمُكَ بِالنَّقِيرِ قَالَ ‏ ‏جِذْعٌ ‏ ‏يُنْقَرُ ثُمَّ يُلْقُونَ فِيهِ مِنْ ‏ ‏الْقُطَيْعَاءِ ‏ ‏أَوْ الثَّمَرِ وَالْمَاءِ حَتَّى إِذَا سَكَنَ غَلَيَانُهُ شَرِبْتُمُوهُ حَتَّى إِنَّ أَحَدَكُمْ لَيَضْرِبُ ابْنَ عَمِّهِ بِالسَّيْفِ وَفِي الْقَوْمِ رَجُلٌ أَصَابَتْهُ جِرَاحَةٌ مِنْ ذَلِكَ فَجَعَلْتُ أُخَبِّئُهَا حَيَاءً مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا فَمَا تَأْمُرُنَا أَنْ نَشْرَبَ قَالَ فِي ‏ ‏الْأَسْقِيَةِ ‏ ‏الَّتِي ‏ ‏يُلَاثُ ‏ ‏عَلَى أَفْوَاهِهَا قَالُوا إِنَّ أَرْضَنَا أَرْضٌ كَثِيرَةُ ‏ ‏الْجُرْذَانِ ‏ ‏لَا تَبْقَى فِيهَا ‏ ‏أَسْقِيَةُ ‏ ‏الْأُدُمِ ‏ ‏قَالَ وَإِنْ أَكَلَتْهُ ‏ ‏الْجُرْذَانُ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏لِأَشَجِّ عَبْدِ الْقَيْسِ ‏ ‏إِنَّ فِيكَ ‏ ‏خُلَّتَيْنِ ‏ ‏يُحِبُّهُمَا اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْحِلْمُ ‏ ‏وَالْأَنَاةُ ‏","","",""],[10747,10747,"","","‏ ‏حَدَّثَنَا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ‏ ‏عَنْ ‏ ‏أَبِي سِعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ فَقَالَ فَقَدِمَ ‏ ‏قَتَادَةُ بْنُ النُّعْمَانِ ‏ ‏أَخُو ‏ ‏أَبِي سَعِيدٍ ‏ ‏لِأُمِّهِ فَقَرَّبُوا إِلَيْهِ مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى فَقَالَ كَأَنَّ هَذَا مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى قَالُوا نَعَمْ فَقَالَ أَلَيْسَ قَدْ نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَوَقَدْ حَدَثَ فِيهِ أَمْرٌ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏نَهَى أَنْ نَحْبِسَهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ ثُمَّ رَخَّصَ لَنَا أَنْ نَأْكُلَ وَنَدَّخِرَ ‏","","",""],[10748,10748,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنْ ‏ ‏يُعْضَدَ ‏ ‏شَجَرُهَا أَوْ ‏ ‏يُخْبَطَ ‏","","",""],[10749,10749,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أُنَيْسِ بْنِ أَبِي يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏اخْتَلَفَ رَجُلَانِ ‏ ‏أَوْ ‏ ‏امْتَرَيَا ‏ ‏رَجُلٌ مَنْ ‏ ‏بَنِي خُدْرَةَ ‏ ‏وَرَجُلٌ مَنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى قَالَ ‏ ‏الْخُدْرِيُّ هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏الْعَمْرِيُّ هُوَ ‏ ‏مَسْجِدُ قُبَاءَ ‏ ‏فَأَتَيَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَاهُ عَنْ ذَلِكَ فَقَالَ هُوَ ‏ ‏هَذَا الْمَسْجِدُ ‏ ‏لِمَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ فِي ذَاكَ خَيْرٌ كَثِيرٌ ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ قُبَاءَ ‏","","",""],[10750,10750,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ السَّرَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ ‏","","",""],[10751,10751,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْمُثَنَّي ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى الْأُسْوَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُودُوا الْمَرِيضَ وَامْشُوا مَعَ الْجَنَائِزِ تُذَكِّرْكُمْ الْآخِرَةَ ‏","","",""],[10752,10752,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏تَعْدِلُ ‏ ‏أَوْ تُعْدَلُ ‏ ‏بِثُلُثِ الْقُرْآنِ ‏","","",""],[10753,10753,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏دَاوُدَ يَعْنِي ابْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏لَمْ تَزَلْ تُخْرَجُ زَكَاةُ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاعٌ ‏ ‏مِنْ تَمْرٍ أَوْ شَعِيرٍ أَوْ ‏ ‏أَقِطٍ ‏ ‏أَوْ زَبِيبٍ ‏","","",""],[10754,10754,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ابْنَةُ كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ هَذِهِ الْأَمْرَاضَ الَّتِي تُصِيبُنَا مَا لَنَا بِهَا قَالَ كَفَّارَاتٌ قَالَ أَبِي وَإِنْ قَلَّتْ قَالَ وَإِنْ شَوْكَةً فَمَا فَوْقَهَا ‏ ‏قَالَ ‏ ‏فَدَعَا ‏ ‏أَبِي ‏ ‏عَلَى نَفْسِهِ أَنْ لَا يُفَارِقَهُ ‏ ‏الْوَعْكُ ‏ ‏حَتَّى يَمُوتَ فِي أَنْ لَا يَشْغَلَهُ عَنْ حَجٍّ وَلَا عُمْرَةٍ وَلَا جِهَادٍ فِي سَبِيلِ اللَّهِ وَلَا صَلَاةٍ مَكْتُوبَةٍ فِي جَمَاعَةٍ فَمَا مَسَّهُ إِنْسَانٌ إِلَّا وَجَدَ حَرَّهُ حَتَّى مَاتَ ‏","","",""],[10755,10755,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اهْتَزَّ الْعَرْشُ لِمَوْتِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏","","",""],[10756,10756,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعْجِبُهُ ‏ ‏الْعَرَاجِينُ ‏ ‏أَنْ يُمْسِكَهَا بِيَدِهِ فَدَخَلَ الْمَسْجِدَ ذَاتَ يَوْمٍ وَفِي يَدِهِ وَاحِدٌ مِنْهَا فَرَأَى ‏ ‏نُخَامَاتٍ ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهُنَّ ‏ ‏بِهِ حَتَّى أَنْقَاهُنَّ ثُمَّ أَقْبَلَ عَلَى النَّاسِ مُغْضَبًا فَقَالَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ أَنْ يَسْتَقْبِلَهُ رَجُلٌ فَيَبْصُقَ فِي وَجْهِهِ إِنَّ أَحَدَكُمْ إِذَا قَامَ إِلَى الصَّلَاةِ فَإِنَّمَا يَسْتَقْبِلُ رَبَّهُ عَزَّ وَجَلَّ وَالْمَلَكُ عَنْ يَمِينِهِ فَلَا يَبْصُقْ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏ ‏أَوْ عَنْ يَسَارِهِ ‏ ‏فَإِنْ عَجِلَتْ بِهِ ‏ ‏بَادِرَةٌ ‏ ‏فَلْيَقُلْ هَكَذَا وَرَدَّ بَعْضَهُ عَلَى بَعْضٍ ‏ ‏وَتَفَلَ ‏ ‏يَحْيَى ‏ ‏فِي ثَوْبِهِ وَدَلَكَهُ ‏","","",""],[10757,10757,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا لَيْلَةَ الْقَدْرِ فَقَالَ بَعْضُ الْقَوْمِ إِنَّهَا تَدُورُ مِنْ السَّنَةِ فَمَشَيْنَا إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ لَيْلَةَ الْقَدْرِ قَالَ نَعَمْ ‏ ‏اعْتَكَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشْرَ الْوَسَطَ مِنْ رَمَضَانَ وَاعْتَكَفْنَا مَعَهُ فَلَمَّا أَصْبَحْنَا صَبِيحَةَ عِشْرِينَ رَجَعَ وَرَجَعْنَا مَعَهُ وَأُرِيَ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيَهَا فَقَالَ ‏ ‏إِنِّي رَأَيْتُ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيتُهَا ‏ ‏فَأُرَانِي أَسْجُدُ فِي مَاءٍ وَطِينٍ فَمَنْ ‏ ‏اعْتَكَفَ ‏ ‏مَعِي فَلْيَرْجِعْ إِلَى ‏ ‏مُعْتَكَفِهِ ‏ ‏ابْتَغُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي ‏ ‏الْوَتْرِ ‏ ‏مِنْهَا وَهَاجَتْ عَلَيْنَا السَّمَاءُ آخِرَ تِلْكَ الْعَشِيَّةِ وَكَانَ نِصْفُ الْمَسْجِدِ ‏ ‏عَرِيشًا ‏ ‏مِنْ جَرِيدٍ ‏ ‏فَوَكَفَ ‏ ‏فَوَالَّذِي هُوَ أَكْرَمَهُ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ لَرَأَيْتُهُ صَلَّى بِنَا صَلَاةَ الْمَغْرِبِ لَيْلَةَ إِحْدَى وَعِشْرِينَ وَإِنَّ جَبْهَتَهُ ‏ ‏وَأَرْنَبَةَ ‏ ‏أَنْفِهِ لَفِي الْمَاءِ وَالطِّينِ ‏","","",""],[10758,10758,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْخَرَّاطِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَقُلْتُ لَهُ كَيْفَ سَمِعْتَ أَبَاكَ يَقُولُ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ بَعْضِ نِسَائِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الْمَسْجِدَيْنِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَأَخَذَ كَفًّا مِنْ حَصًى فَضَرَبَ بِهِ الْأَرْضَ قَالَ ‏ ‏هُوَ هَذَا ‏ ‏مَسْجِدُ الْمَدِينَةِ ‏ ‏قَالَ فَقُلْتُ لَهُ أَتَشْهَدُ لَسَمِعْتَ أَبَاكَ هَكَذَا يَذْكُرُهُ ‏","","",""],[10759,10759,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَصَابَ الْمُسْلِمَ مِنْ مَرَضٍ وَلَا ‏ ‏وَصَبٍ ‏ ‏وَلَا حَزَنٍ حَتَّى الْهَمَّ يُهِمُّهُ إِلَّا يُكَفِّرُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ مِنْ خَطَايَاهُ ‏","","",""],[10760,10760,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي طَعَامِ أَحَدِكُمْ ‏ ‏فَامْقُلُوهُ ‏","","",""],[10761,10761,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَشُعْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلْيَؤُمَّهُمْ أَحَدُهُمْ وَأَحَقُّهُمْ بِالْإِمَامَةِ أَقْرَؤُهُمْ ‏","","",""],[10762,10762,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏حُنَيْنٍ ‏ ‏لِسَبْعَ عَشْرَةَ ‏ ‏أَوْ ثَمَانِ عَشْرَةَ ‏ ‏مَضَتْ مِنْ رَمَضَانَ ‏ ‏فَصَامَ صَائِمُونَ وَأَفْطَرَ آخَرُونَ وَلَمْ يَعِبْ هَؤُلَاءِ عَلَى هَؤُلَاءِ وَلَا هَؤُلَاءِ عَلَى هَؤُلَاءِ ‏","","",""],[10763,10763,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَكُونُ أُمَرَاءُ ‏ ‏تَغْشَاهُمْ غَوَاشٍ ‏ ‏أَوْ حَوَاشٍ ‏ ‏مِنْ النَّاسِ يَظْلِمُونَ وَيَكْذِبُونَ فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَيُصَدِّقْهُمْ بِكَذِبِهِمْ وَيُعِنْهُمْ عَلَى ظُلْمِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ ‏","","",""],[10764,10764,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ ‏ ‏ابْنَ صَائِدٍ ‏ ‏عَنْ تُرْبَةِ الْجَنَّةِ فَقَالَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ مِسْكٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[10765,10765,"","","‏ ‏رَحِمَهُ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ ‏ ‏ابْنَ صَائِدٍ ‏ ‏عَنْ تُرْبَةِ الْجَنَّةِ فَقَالَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ مِسْكٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[10766,10766,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الْجَنَازَةَ فَقُومُوا ‏ ‏لَهَا ‏ ‏فَمَنْ اتَّبَعَهَا فَلَا يَقْعُدْ حَتَّى تُوضَعَ ‏","","",""],[10767,10767,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَرِقُ أُمَّتِي فِرْقَتَيْنِ ‏ ‏فَيَتَمَرَّقُ ‏ ‏بَيْنَهُمَا ‏ ‏مَارِقَةٌ ‏ ‏يَقْتُلُهَا أَوْلَى الطَّائِفَتَيْنِ بِالْحَقِّ ‏","","",""],[10768,10768,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عِيَاضٌ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ الْمَسْجِدَ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَدَعَاهُ فَأَمَرَهُ أَنْ يُصَلِّيَ رَكْعَتَيْنِ ثُمَّ دَخَلَ الْجُمُعَةَ الثَّانِيَةَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَدَعَاهُ فَأَمَرَهُ ثُمَّ دَخَلَ الْجُمُعَةَ الثَّالِثَةَ ‏ ‏فَأَمَرَهُ أَنْ يُصَلِّيَ رَكْعَتَيْنِ ثُمَّ قَالَ تَصَدَّقُوا فَفَعَلُوا فَأَعْطَاهُ ثَوْبَيْنِ مِمَّا تَصَدَّقُوا ثُمَّ قَالَ تَصَدَّقُوا فَأَلْقَى أَحَدَ ثَوْبَيْهِ ‏ ‏فَانْتَهَرَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَرِهَ مَا صَنَعَ ثُمَّ قَالَ انْظُرُوا إِلَى هَذَا فَإِنَّهُ دَخَلَ الْمَسْجِدَ فِي هَيْئَةٍ ‏ ‏بَذَّةٍ ‏ ‏فَدَعَوْتُهُ فَرَجَوْتُ أَنْ تُعْطُوا لَهُ فَتَصَدَّقُوا عَلَيْهِ وَتَكْسُوهُ فَلَمْ تَفْعَلُوا فَقُلْتُ تَصَدَّقُوا فَتَصَدَّقُوا فَأَعْطَيْتُهُ ثَوْبَيْنِ مِمَّا تَصَدَّقُوا ثُمَّ قُلْتُ تَصَدَّقُوا فَأَلْقَى أَحَدَ ثَوْبَيْهِ خُذْ ثَوْبَكَ وَانْتَهَرَهُ ‏","","",""],[10769,10769,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏حُبِسْنَا يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏عَنْ الصَّلَوَاتِ حَتَّى كَانَ بَعْدَ الْمَغْرِبِ ‏ ‏هَوِيًّا ‏ ‏وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ فِي الْقِتَالِ مَا نَزَلَ فَلَمَّا كُفِينَا الْقِتَالَ وَذَلِكَ قَوْلُهُ ‏ { ‏وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا ‏} ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ الظُّهْرَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَقَامَ الْعَصْرَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَقَامَ الْمَغْرِبَ فَصَلَّاهَا كَمَا يُصَلِّيهَا فِي وَقْتِهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ وَزَادَ فِيهِ قَالَ وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ صَلَاةَ الْخَوْفِ ‏ { ‏فَرِجَالًا أَوْ رُكْبَانًا ‏}","","",""],[10770,10770,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏يُعْرَضُ النَّاسُ عَلَى جِسْرِ جَهَنَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏وَكَلَالِيبُ ‏ ‏وَخَطَاطِيفُ ‏ ‏تَخْطَفُ النَّاسَ قَالَ فَيَمُرُّ النَّاسُ مِثْلَ الْبَرْقِ وَآخَرُونَ مِثْلَ الرِّيحِ وَآخَرُونَ مِثْلَ الْفَرَسِ الْمُجِدِّ وَآخَرُونَ يَسْعَوْنَ سَعْيًا وَآخَرُونَ يَمْشُونَ مَشْيًا وَآخَرُونَ يَحْبُونَ حَبْوًا وَآخَرُونَ يَزْحَفُونَ زَحْفًا فَأَمَّا أَهْلُ النَّارِ فَلَا يَمُوتُونَ وَلَا يَحْيَوْنَ وَأَمَّا نَاسٌ فَيُؤْخَذُونَ بِذُنُوبِهِمْ فَيُحْرَقُونَ فَيَكُونُونَ فَحْمًا ثُمَّ يَأْذَنُ اللَّهُ فِي ‏ ‏الشَّفَاعَةِ ‏ ‏فَيُوجَدُونَ ‏ ‏ضِبَارَاتٍ ‏ ‏ضِبَارَاتٍ ‏ ‏فَيُقْذَفُونَ عَلَى نَهَرٍ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ رَأَيْتُمْ ‏ ‏الصَّبْغَاءَ ‏ ‏فَقَالَ وَعَلَى النَّارِ ثَلَاثُ شَجَرَاتٍ فَتَخْرُجُ ‏ ‏أَوْ يَخْرُجُ ‏ ‏رَجُلٌ مِنْ النَّارِ فَيَكُونُ عَلَى شَفَتِهَا فَيَقُولُ يَا رَبِّ اصْرِفْ وَجْهِي عَنْهَا قَالَ فَيَقُولُ ‏ ‏وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى شَجَرَةً فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَآكُلُ مِنْ ثَمَرَتِهَا قَالَ فَيَقُولُ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى شَجَرَةً أُخْرَى أَحْسَنَ مِنْهَا فَيَقُولُ يَا رَبِّ حَوِّلْنِي إِلَى هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَآكُلَ مِنْ ثَمَرَتِهَا فَيَقُولُ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى الثَّالِثَةَ فَيَقُولُ يَا رَبِّ حَوِّلْنِي إِلَى هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَآكُلُ مِنْ ثَمَرَتِهَا قَالَ وَعَهْدِكَ وَذِمَّتِكَ لَا تَسْأَلُنِي غَيْرَهَا قَالَ فَيَرَى سَوَادَ النَّاسِ وَيَسْمَعُ ‏ ‏أَصْوَاتَهُمْ فَيَقُولُ رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَرَجُلٌ ‏ ‏آخَرُ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَلَفَا فَقَالَ أَحَدُهُمَا فَيَدْخُلُ الْجَنَّةَ ‏ ‏فَيُعْطَى الدُّنْيَا وَمِثْلَهَا مَعَهَا وَقَالَ الْآخَرُ يُدْخَلُ الْجَنَّةَ ‏ ‏فَيُعْطَى الدُّنْيَا وَعَشَرَةَ أَمْثَالِهَا ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَمُرُّ النَّاسُ عَلَى جِسْرِ جَهَنَّمَ فَذَكَرَهُ قَالَ بِجَنْبَتَيْهِ مَلَائِكَةٌ يَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ وَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا رَأَيْتُمْ ‏ ‏الصَّبْغَاءَ شَجَرَةٌ تَنْبُتُ فِي ‏ ‏الْغُثَاءِ ‏ ‏وَقَالَ وَأَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏وَأَمْلَاهُ عَلَيَّ قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّفَاعَةَ ‏ ‏فَقَالَ إِنَّ النَّاسَ يُعْرَضُونَ عَلَى جِسْرِ جَهَنَّمَ وَعَلَيْهِ ‏ ‏حَسَكٌ ‏ ‏وَكَلَالِيبُ ‏ ‏يَخْطَفُ النَّاسَ وَبِجَنْبَتَيْهِ الْمَلَائِكَةُ يَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[10771,10771,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏أَيُّوبُ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُثَنَّى ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏مَرْوَانَ ‏ ‏فَدَخَلَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ النَّفْخِ فِي الشَّرَابِ قَالَ نَعَمْ فَقَالَ رَجُلٌ إِنِّي لَا ‏ ‏أُرْوَى مِنْ نَفَسٍ وَاحِدٍ قَالَ أَبِنْهُ عَنْكَ ثُمَّ تَنَفَّسْ قَالَ أَرَى فِيهِ ‏ ‏الْقَذَاةَ ‏ ‏قَالَ ‏ ‏فَأَهْرِقْهَا ‏","","",""],[10772,10772,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْعَزْلِ ‏ ‏قَالَ ‏ ‏اصْنَعُوا مَا بَدَا لَكُمْ فَإِنْ قَدَّرَ اللَّهُ شَيْئًا كَانَ ‏","","",""],[10773,10773,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قُلْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حُرِّمَتْ الْخَمْرُ ‏ ‏إِنَّ عِنْدَنَا خَمْرًا لِيَتِيمٍ لَنَا فَأَمَرَنَا ‏ ‏فَأَهْرَقْنَاهَا ‏","","",""],[10774,10774,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى لَيَرَوْنَ مَنْ فَوْقَهُمْ كَمَا تَرَوْنَ الْكَوْكَبَ الدُّرِّيَّ فِي أُفُقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[10775,10775,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ذَكْوَانَ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى مَنْزِلَ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَخَرَجَ وَرَأْسُهُ يَقْطُرُ قَالَ لَعَلَّنَا أَعْجَلْنَاكَ قَالَ ‏ ‏إِذَا أُعْجِلْتَ ‏ ‏أَوْ ‏ ‏أُقْحِطْتَ ‏ ‏فَلَيْسَ عَلَيْكَ غُسْلٌ ‏","","",""],[10776,10776,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ لَا تُوقِدُوا نَارًا بِلَيْلٍ قَالَ فَلَمَّا كَانَ بَعْدَ ذَاكَ قَالَ ‏ ‏أَوْقِدُوا وَاصْطَنِعُوا فَإِنَّهُ لَا ‏ ‏يُدْرِكُ ‏ ‏قَوْمٌ بَعْدَكُمْ ‏ ‏صَاعَكُمْ ‏ ‏وَلَا ‏ ‏مُدَّكُمْ ‏","","",""],[10777,10777,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَقِيَنِي ‏ ‏ابْنُ صَائِدٍ ‏ ‏فَقَالَ عُدَّ النَّاسَ يَقُولُونَ ‏ ‏أَوْ أَحْسِبُ النَّاسَ يَقُولُونَ ‏ ‏وَأَنْتُمْ يَا ‏ ‏أَصْحَابَ ‏ ‏مُحَمَّدٍ ‏ ‏أَلَيْسَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَوْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ يَهُودِيٌّ وَأَنَا مُسْلِمٌ وَإِنَّهُ أَعْوَرُ وَأَنَا صَحِيحٌ وَلَا يَأْتِي ‏ ‏مَكَّةَ ‏ ‏وَلَا ‏ ‏الْمَدِينَةَ ‏ ‏وَقَدْ حَجَجْتُ وَأَنَا مَعَكَ الْآنَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَلَا يُولَدُ لَهُ وَقَدْ وُلِدَ لِي ثُمَّ قَالَ مَعَ ذَاكَ إِنِّي لَأَعْلَمُ أَيْنَ وُلِدَ وَمَتَى يَخْرُجُ وَأَيْنَ هُوَ قَالَ فَلَبَّسَ عَلَيَّ ‏","","",""],[10778,10778,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصُومُ عَبْدٌ يَوْمًا فِي سَبِيلِ اللَّهِ إِلَّا بَاعَدَ اللَّهُ بِذَلِكَ الْيَوْمِ النَّارَ عَنْ وَجْهِهِ سَبْعِينَ خَرِيفًا ‏","","",""],[10779,10779,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي قَدْ تَرَكْتُ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ كِتَابُ اللَّهِ عَزَّ وَجَلَّ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي أَلَا إِنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ ‏","","",""],[10780,10780,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي الْجُهَنِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدًا الْعَمِّيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الصِّدِّيقِ النَّاجِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ مِنْ أُمَّتِي ‏ ‏الْمَهْدِيُّ ‏ ‏فَإِنْ طَالَ عُمْرُهُ أَوْ قَصُرَ عُمْرُهُ عَاشَ سَبْعَ سِنِينَ أَوْ ثَمَانِ سِنِينَ أَوْ تِسْعَ سِنِينَ يَمْلَأُ الْأَرْضَ قِسْطًا وَعَدْلًا وَتُخْرِجُ الْأَرْضُ نَبَاتَهَا وَتُمْطِرُ السَّمَاءُ قَطْرَهَا ‏","","",""],[10781,10781,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏عَطِيَّةُ بْنُ سَعْدٍ ‏ ‏بِبَابِ هَذَا الْمَسْجِدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى ‏ ‏لَيَرَاهُمْ مَنْ تَحْتَهُمْ كَمَا تَرَوْنَ النَّجْمَ الطَّالِعَ فِي الْأُفُقِ مِنْ آفَاقِ السَّمَاءِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[10782,10782,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ لَيُسْأَلُ يَوْمَ الْقِيَامَةِ حَتَّى يَكُونَ فِيمَا يُسْأَلُ عَنْهُ أَنْ يُقَالَ ‏ ‏مَا مَنَعَكَ أَنْ تُنْكِرَ الْمُنْكَرَ إِذْ رَأَيْتَهُ قَالَ فَمَنْ لَقَّنَهُ اللَّهُ حُجَّتَهُ قَالَ رَبِّ رَجَوْتُكَ وَخِفْتُ النَّاسَ ‏","","",""],[10783,10783,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَجَدَ رَجُلٌ فِي مَنْزِلِهِ حَيَّةً فَأَخَذَ رُمْحَهُ فَشَكَّهَا فِيهِ فَلَمْ تَمُتْ الْحَيَّةُ حَتَّى مَاتَ الرَّجُلُ فَأُخْبِرَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ مَعَكُمْ ‏ ‏عَوَامِرَ ‏ ‏فَإِذَا رَأَيْتُمْ مِنْهُمْ شَيْئًا ‏ ‏فَحَرِّجُوا ‏ ‏عَلَيْهِ ثَلَاثًا فَإِنْ رَأَيْتُمُوهُ بَعْدَ ذَلِكَ فَاقْتُلُوهُ ‏","","",""],[10784,10784,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي الْعَيَّاشِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏أَدْنَى ‏ ‏أَهْلِ الْجَنَّةِ مَنْزِلَةً رَجُلٌ صَرَفَ اللَّهُ وَجْهَهُ عَنْ النَّارِ قِبَلَ الْجَنَّةِ وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ فَقَالَ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ فَأَكُونَ فِي ظِلِّهَا فَقَالَ اللَّهُ ‏ ‏هَلْ عَسَيْتَ إِنْ فَعَلْتُ أَنْ تَسْأَلَنِي غَيْرَهَا قَالَ لَا وَعِزَّتِكَ فَقَدَّمَهُ اللَّهُ إِلَيْهَا وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ وَثَمَرٍ فَقَالَ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا وَآكُلُ مِنْ ثَمَرِهَا فَقَالَ اللَّهُ لَهُ هَلْ عَسَيْتَ إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَتُمَثَّلُ لَهُ شَجَرَةٌ أُخْرَى ذَاتُ ظِلٍّ وَثَمَرٍ وَمَاءٍ فَيَقُولُ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا وَآكُلُ مِنْ ثَمَرِهَا وَأَشْرَبُ مِنْ مَائِهَا فَيَقُولُ لَهُ هَلْ عَسَيْتَ إِنْ فَعَلْتُ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَيَبْرُزُ لَهُ بَابُ الْجَنَّةِ فَيَقُولُ أَيْ رَبِّ قَدِّمْنِي إِلَى بَابِ الْجَنَّةِ فَأَكُونَ تَحْتَ ‏ ‏نِجَافِ ‏ ‏الْجَنَّةِ وَأَنْظُرَ إِلَى أَهْلِهَا فَيُقَدِّمُهُ اللَّهُ إِلَيْهَا فَيَرَى أَهْلَ الْجَنَّةِ وَمَا فِيهَا فَيَقُولُ أَيْ رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَيُدْخِلُهُ اللَّهُ الْجَنَّةَ قَالَ فَإِذَا دَخَلَ الْجَنَّةَ قَالَ هَذَا لِي قَالَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُ تَمَنَّ فَيَتَمَنَّى وَيُذَكِّرُهُ اللَّهُ سَلْ مِنْ كَذَا وَكَذَا حَتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ عَزَّ وَجَلَّ هُوَ لَكَ وَعَشَرَةُ أَمْثَالِهِ قَالَ ثُمَّ يَدْخُلُ الْجَنَّةَ يَدْخُلُ عَلَيْهِ زَوْجَتَاهُ مِنْ الْحُورِ الْعِينِ فَيَقُولَانِ لَهُ الْحَمْدُ لِلَّهِ الَّذِي أَحْيَاكَ لَنَا وَأَحْيَانَا لَكَ فَيَقُولُ مَا أُعْطِيَ أَحَدٌ مِثْلَ مَا أُعْطِيتُ قَالَ ‏ ‏وَأَدْنَى ‏ ‏أَهْلِ النَّارِ عَذَابًا يُنْعَلُ مَنْ نَارٍ بِنَعْلَيْنِ يَغْلِي دِمَاغُهُ مِنْ حَرَارَةِ نَعْلَيْهِ ‏","","",""],[10785,10785,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُحَجَّنَّ ‏ ‏الْبَيْتُ ‏ ‏وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[10786,10786,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْأَنْصَارِيِّ ‏ ‏وَأَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَاءَ إِلَى جَنَازَةٍ فَمَشَى مَعَهَا مِنْ أَهْلِهَا حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ انْتَظَرَ حَتَّى تُدْفَنَ ‏ ‏أَوْ يُفْرَغَ مِنْهَا ‏ ‏فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10787,10787,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُحَجَّنَّ هَذَا ‏ ‏الْبَيْتُ ‏ ‏وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[10788,10788,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأَقُولُ أَصْحَابِي أَصْحَابِي فَقِيلَ إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ قَالَ فَأَقُولُ بُعْدًا بُعْدًا ‏ ‏أَوْ قَالَ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏ ‏لِمَنْ بَدَّلَ بَعْدِي ‏","","",""],[10789,10789,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[10790,10790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏مَنَّانٌ ‏ ‏وَلَا ‏ ‏عَاقٌّ ‏ ‏وَلَا مُدْمِنُ خَمْرٍ ‏","","",""],[10791,10791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مَطَرٌ ‏ ‏وَالْمُعَلَّى ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُمْلَأُ الْأَرْضُ ظُلْمًا ‏ ‏وَجَوْرًا ‏ ‏ثُمَّ يَخْرُجُ رَجُلٌ مِنْ ‏ ‏عِتْرَتِي ‏ ‏يَمْلِكُ سَبْعًا أَوْ تِسْعًا فَيَمْلَأُ الْأَرْضَ قِسْطًا وَعَدْلًا ‏","","",""],[10792,10792,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ عَلَيْكُمْ أُمَرَاءُ تَطْمَئِنُّ إِلَيْهِمْ الْقُلُوبُ وَتَلِينُ لَهُمْ الْجُلُودُ ثُمَّ يَكُونُ عَلَيْكُمْ أُمَرَاءُ تَشْمَئِزُّ مِنْهُمْ الْقُلُوبُ وَتَقْشَعِرُّ مِنْهُمْ الْجُلُودُ فَقَالَ رَجُلٌ أَنُقَاتِلُهُمْ يَا رَسُولَ اللَّهِ قَالَ لَا مَا أَقَامُوا الصَّلَاةَ ‏","","",""],[10793,10793,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ صُهَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اشْتَكَيْتَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قَالَ نَعَمْ قَالَ ‏ ‏بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ مِنْ شَرِّ كُلِّ نَفْسٍ وَعَيْنٍ ‏ ‏يَشْفِيكَ بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ ‏","","",""],[10794,10794,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْطِرُ يَوْمَ الْفِطْرِ قَبْلَ أَنْ يَخْرُجَ وَكَانَ لَا ‏ ‏يُصَلِّي قَبْلَ الصَّلَاةِ فَإِذَا قَضَى صَلَاتَهُ صَلَّى رَكْعَتَيْنِ ‏","","",""],[10795,10795,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَاضِرُ بْنُ الْمُوَرِّعِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏غَشِيَ ‏ ‏أَحَدُكُمْ أَهْلَهُ ثُمَّ أَرَادَ أَنْ يَعُودَ فَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[10796,10796,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ وَهْبٍ ‏ ‏وَأَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏سَبْيِ ‏ ‏أَوْطَاسٍ ‏ ‏لَا ‏ ‏يَقَعُ ‏ ‏عَلَى حَامِلٍ حَتَّى تَضَعَ وَغَيْرِ حَامِلٍ حَتَّى تَحِيضَ حَيْضَةً ‏","","",""],[10797,10797,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏و سَمِعْت ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ بْنِ مُسَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ شَيْئًا أَقْبَلَ رَجُلٌ ‏ ‏فَأَكَبَّ ‏ ‏عَلَيْهِ فَطَعَنَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعُرْجُونٍ ‏ ‏كَانَ مَعَهُ فَجُرِحَ بِوَجْهِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَالَ ‏ ‏فَاسْتَقِدْ ‏ ‏قَالَ قَدْ عَفَوْتُ يَا رَسُولَ اللَّهِ ‏","","",""],[10798,10798,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ أَحَدَكُمْ يَعْمَلُ فِي صَخْرَةٍ صَمَّاءَ لَيْسَ لَهَا بَابٌ وَلَا ‏ ‏كُوَّةٌ ‏ ‏لَخَرَجَ عَمَلُهُ لِلنَّاسِ كَائِنًا مَا كَانَ ‏","","",""],[10799,10799,"","","‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ دَلْوًا مِنْ ‏ ‏غَسَّاقٍ ‏ ‏يُهَرَاقُ ‏ ‏فِي الدُّنْيَا لَأَنْتَنَ أَهْلَ الدُّنْيَا ‏","","",""],[10800,10800,"","","‏ ‏وَعَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَأْكُلُ التُّرَابُ كُلَّ شَيْءٍ مِنْ الْإِنْسَانِ إِلَّا ‏ ‏عَجْبَ ‏ ‏ذَنَبِهِ قِيلَ وَمِثْلُ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ مِثْلُ حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْهُ تَنْبُتُونَ ‏","","",""]];
